const COMMON_QUIZ_5 = [
  // ==================== 物理（100题）====================
  // 力学（20题）
  { q: "牛顿第一定律又称为？", options: ["惯性定律", "加速度定律", "作用力与反作用力定律", "万有引力定律"], answer: 0, explanation: "牛顿第一定律又称惯性定律，指出一切物体在没有受到外力作用时，总保持匀速直线运动状态或静止状态。该定律揭示了物体的惯性性质。" },
  { q: "牛顿第二定律的数学表达式是？", options: ["F=ma", "F=mv", "E=mc²", "P=mv"], answer: 0, explanation: "牛顿第二定律的数学表达式为F=ma，即物体的加速度与所受合外力成正比，与物体质量成反比。这是经典力学的核心定律之一。" },
  { q: "牛顿第三定律的内容是？", options: ["作用力与反作用力大小相等、方向相反", "力等于质量乘以加速度", "物体保持原有运动状态", "万有引力与距离平方成反比"], answer: 0, explanation: "牛顿第三定律指出，两个物体之间的作用力和反作用力总是大小相等、方向相反，作用在同一条直线上。例如人走路时脚向后蹬地，地面给脚向前的反作用力。" },
  { q: "万有引力定律是谁提出的？", options: ["牛顿", "爱因斯坦", "伽利略", "开普勒"], answer: 0, explanation: "万有引力定律由牛顿在1687年提出，指出任何两个物体之间都存在引力，引力大小与两物体质量的乘积成正比，与它们之间距离的平方成反比。" },
  { q: "质量为2kg的物体，受到10N的合外力作用，其加速度为？", options: ["5m/s²", "20m/s²", "8m/s²", "0.2m/s²"], answer: 0, explanation: "根据牛顿第二定律F=ma，a=F/m=10N/2kg=5m/s²。加速度方向与合外力方向相同。" },
  { q: "功的国际单位是？", options: ["焦耳", "瓦特", "牛顿", "帕斯卡"], answer: 0, explanation: "功的国际单位是焦耳（J），1焦耳等于1牛顿的力使物体在力的方向上移动1米所做的功，即1J=1N·m。" },
  { q: "功率的国际单位是？", options: ["瓦特", "焦耳", "牛顿", "安培"], answer: 0, explanation: "功率的国际单位是瓦特（W），1瓦特等于1焦耳每秒（1W=1J/s），表示单位时间内做功的多少。" },
  { q: "动能的表达式是？", options: ["Ek=½mv²", "Ek=mv", "Ek=mgh", "Ek=½kx²"], answer: 0, explanation: "动能表达式为Ek=½mv²，即物体的动能等于其质量与速度平方乘积的一半。动能是标量，只有大小没有方向。" },
  { q: "重力势能的表达式是？", options: ["Ep=mgh", "Ep=½mv²", "Ep=½kx²", "Ep=F/S"], answer: 0, explanation: "重力势能表达式为Ep=mgh，其中m为质量，g为重力加速度，h为物体相对参考面的高度。重力势能与参考面的选取有关。" },
  { q: "动量守恒定律适用的条件是？", options: ["系统不受外力或所受合外力为零", "系统内力为零", "系统不受任何力", "系统加速度为零"], answer: 0, explanation: "动量守恒定律指出，当系统不受外力或所受合外力为零时，系统的总动量保持不变。动量守恒是自然界最基本的守恒定律之一。" },
  { q: "动量的表达式是？", options: ["p=mv", "p=ma", "p=½mv²", "p=mgh"], answer: 0, explanation: "动量表达式为p=mv，即物体的动量等于质量与速度的乘积。动量是矢量，方向与速度方向相同。国际单位为kg·m/s。" },
  { q: "下列关于惯性的说法，正确的是？", options: ["一切物体都具有惯性", "只有运动的物体才有惯性", "只有静止的物体才有惯性", "速度越大惯性越大"], answer: 0, explanation: "一切物体都具有惯性，惯性是物体的固有属性，与物体是否运动、运动快慢无关。质量是惯性大小的唯一量度，质量越大惯性越大。" },
  { q: "宇航员在月球上举起同一物体比在地球上？", options: ["更省力，因为月球引力小", "更费力，因为月球引力大", "一样费力", "无法举起"], answer: 0, explanation: "月球表面重力加速度约为地球的1/6，因此同一物体在月球上的重力约为地球上的1/6，宇航员在月球上举物更省力。但物体的质量不变。" },
  { q: "下列现象中，属于利用惯性的是？", options: ["运动员跳远时助跑", "系安全带", "汽车限速", "保持车距"], answer: 0, explanation: "运动员跳远助跑是利用惯性，助跑使身体获得较大速度，起跳后由于惯性继续向前运动从而跳得更远。系安全带、限速、保持车距都是防止惯性带来的危害。" },
  { q: "一物体从高处自由下落，不计空气阻力，下列说法正确的是？", options: ["机械能守恒", "动能减小", "重力势能增大", "加速度增大"], answer: 0, explanation: "自由下落时只有重力做功，机械能守恒。下落过程中重力势能转化为动能，重力势能减小、动能增大，但机械能总量不变。加速度恒为g。" },
  { q: "弹簧测力计的工作原理是？", options: ["在弹性限度内，弹簧的伸长与所受拉力成正比", "弹簧的伸长与拉力成反比", "弹簧的伸长与拉力无关", "弹簧的伸长与拉力平方成正比"], answer: 0, explanation: "弹簧测力计原理是在弹性限度内，弹簧的伸长量与所受拉力成正比（胡克定律）。据此可将力的大小转化为弹簧形变量来测量。" },
  { q: "压强的公式是？", options: ["P=F/S", "P=FS", "P=F+S", "P=F/S²"], answer: 0, explanation: "压强公式为P=F/S，即压强等于压力除以受力面积。压强的国际单位是帕斯卡（Pa），1Pa=1N/m²。减小受力面积可以增大压强。" },
  { q: "液体压强的计算公式是？", options: ["P=ρgh", "P=ρgV", "P=ρgh/S", "P=ρVg"], answer: 0, explanation: "液体压强公式为P=ρgh，其中ρ为液体密度，g为重力加速度，h为液体深度。液体压强只与液体密度和深度有关，与容器形状无关。" },
  { q: "阿基米德原理的内容是？", options: ["浮力等于物体排开液体的重力", "浮力等于物体的重力", "浮力等于液体的重力", "浮力等于物体的体积乘以液体密度"], answer: 0, explanation: "阿基米德原理指出，浸在液体中的物体受到的浮力等于它排开液体的重力，即F浮=ρ液gV排。该原理同样适用于气体。" },
  { q: "杠杆平衡条件是？", options: ["动力乘以动力臂等于阻力乘以阻力臂", "动力=阻力", "动力臂=阻力臂", "动力乘以阻力=动力臂乘以阻力臂"], answer: 0, explanation: "杠杆平衡条件是动力×动力臂=阻力×阻力臂（F1·L1=F2·L2）。当动力臂大于阻力臂时为省力杠杆，反之为费力杠杆。" },

  // 热学（15题）
  { q: "热力学第零定律描述的是？", options: ["热平衡的概念", "能量守恒", "熵增原理", "绝对零度不可达到"], answer: 0, explanation: "热力学第零定律描述热平衡概念：如果两个系统分别与第三个系统处于热平衡，则这两个系统也彼此处于热平衡。这一定律奠定了温度测量的基础。" },
  { q: "热力学第一定律实际上是？", options: ["能量守恒定律在热学中的体现", "熵增原理", "热平衡定律", "绝对零度不可达原理"], answer: 0, explanation: "热力学第一定律是能量守恒定律在热学中的体现，表述为系统内能的改变等于外界对系统做的功与系统从外界吸收的热量之和。" },
  { q: "热力学第二定律的克劳修斯表述是？", options: ["热量不能自发地从低温物体传到高温物体", "能量守恒", "热平衡定律", "绝对零度不可达到"], answer: 0, explanation: "热力学第二定律的克劳修斯表述为：热量不能自发地从低温物体传到高温物体。这揭示了热传导的方向性，即自然过程是不可逆的。" },
  { q: "热力学第二定律的开尔文表述是？", options: ["不可能从单一热源吸取热量使之完全变为有用功而不产生其他影响", "能量可以消灭", "热量能自发从低温传到高温", "绝对零度可以达到"], answer: 0, explanation: "开尔文表述为：不可能从单一热源吸取热量使之完全变为有用功而不产生其他影响。这否定了第二类永动机的可能性。" },
  { q: "热力学第三定律的内容是？", options: ["绝对零度不可能通过有限步骤达到", "能量守恒", "热量从高温传到低温", "熵增原理"], answer: 0, explanation: "热力学第三定律指出，绝对零度（0K或-273.15°C）不可能通过有限步骤达到。绝对零度是温度的理论下限，此时分子运动停止。" },
  { q: "摄氏温度与开尔文温度的换算关系是？", options: ["T(K)=t(°C)+273.15", "T(K)=t(°C)-273.15", "T(K)=t(°C)×273.15", "T(K)=t(°C)/273.15"], answer: 0, explanation: "热力学温度（开尔文温度）与摄氏温度的换算关系为T(K)=t(°C)+273.15。例如0°C对应273.15K，100°C对应373.15K。" },
  { q: "下列关于温度和热量的说法，正确的是？", options: ["温度是分子热运动平均动能的标志", "温度高的物体热量多", "热量从热量多的物体传向热量少的物体", "0°C的物体没有内能"], answer: 0, explanation: "温度是分子热运动平均动能的标志。热量是热传递过程中传递的能量，不是物体含有的量。热量从高温物体传向低温物体。任何温度的物体都有内能。" },
  { q: "晶体熔化的特点是？", options: ["熔化时温度不变，吸收热量", "熔化时温度升高，吸收热量", "熔化时温度降低，放出热量", "熔化时温度不变，放出热量"], answer: 0, explanation: "晶体熔化时不断吸收热量但温度保持不变（熔点温度），吸收的热量用于破坏分子间的规则排列。非晶体熔化时温度持续升高，没有固定熔点。" },
  { q: "比热容最大的常见液体是？", options: ["水", "酒精", "煤油", "水银"], answer: 0, explanation: "水的比热容最大（4.2×10³J/(kg·°C)），这意味着水吸收或放出较多热量时温度变化较小。水的这一特性使其成为良好的冷却剂和保温剂，也调节了地球气候。" },
  { q: "下列物态变化中，属于吸热过程的是？", options: ["升华", "凝华", "液化", "凝固"], answer: 0, explanation: "升华（固态直接变气态）是吸热过程。凝华、液化、凝固都是放热过程。常见的升华现象如干冰升华、樟脑丸升华等。" },
  { q: "夏天从冰箱拿出的饮料瓶外壁出现水珠，这是哪种物态变化？", options: ["液化", "汽化", "凝固", "升华"], answer: 0, explanation: "空气中的水蒸气遇到冷的饮料瓶壁，液化成小水珠附着在瓶壁上。液化是气态变为液态的过程，需要放热。" },
  { q: "热传递的三种方式是？", options: ["热传导、热对流、热辐射", "热传导、热对流、热扩散", "热辐射、热传导、热交换", "热对流、热辐射、热蒸发"], answer: 0, explanation: "热传递的三种方式是热传导（固体中主要通过分子碰撞传热）、热对流（流体中通过流动传热）和热辐射（通过电磁波传热，不需要介质）。" },
  { q: "下列关于比热容的说法，正确的是？", options: ["水的比热容较大，沿海地区昼夜温差小", "比热容越大的物体越容易升温", "比热容与物质种类无关", "比热容的单位是焦耳"], answer: 0, explanation: "水的比热容较大，吸收或放出相同热量时温度变化小，因此沿海地区受海洋调节昼夜温差较小。比热容是物质的特性，与物质种类有关，单位为J/(kg·°C)。" },
  { q: "能量转化过程中遵循的基本规律是？", options: ["能量守恒定律", "质量守恒定律", "动量守恒定律", "电荷守恒定律"], answer: 0, explanation: "能量转化遵循能量守恒定律，能量既不会凭空产生也不会凭空消失，只能从一种形式转化为另一种形式，或从一个物体转移到另一个物体，总量保持不变。" },
  { q: "内能与下列哪个因素有关？", options: ["温度、质量、状态", "体积、密度", "速度、高度", "压力、流量"], answer: 0, explanation: "物体的内能与温度、质量、状态（物态）等因素有关。内能是物体内所有分子动能和分子势能的总和。温度越高、质量越大，内能越大。" },

  // 电磁学（20题）
  { q: "自然界中存在几种电荷？", options: ["两种：正电荷和负电荷", "一种", "三种", "四种"], answer: 0, explanation: "自然界中存在两种电荷：正电荷和负电荷。同种电荷相互排斥，异种电荷相互吸引。电荷的最小单位是元电荷e=1.6×10⁻¹⁹C。" },
  { q: "库仑定律的数学表达式是？", options: ["F=kq₁q₂/r²", "F=kq₁q₂/r", "F=q₁q₂/r²", "F=kq₁+q₂/r²"], answer: 0, explanation: "库仑定律表达式为F=kq₁q₂/r²，即两个点电荷之间的作用力与它们电荷量的乘积成正比，与它们之间距离的平方成反比。k为静电力常量。" },
  { q: "电场强度的定义是？", options: ["单位电荷所受的电场力", "单位电荷的电量", "单位面积上的电荷量", "单位距离的电势差"], answer: 0, explanation: "电场强度E定义为单位电荷在电场中所受的力，E=F/q。电场强度是矢量，方向为正电荷在该点所受电场力的方向。单位为N/C或V/m。" },
  { q: "电流的方向规定为？", options: ["正电荷定向移动的方向", "负电荷定向移动的方向", "电子移动的方向", "自由电子移动的方向"], answer: 0, explanation: "电流方向规定为正电荷定向移动的方向。在金属导体中，实际移动的是带负电的自由电子，其移动方向与电流方向相反。" },
  { q: "欧姆定律的表达式是？", options: ["I=U/R", "I=UR", "I=R/U", "I=U/R²"], answer: 0, explanation: "欧姆定律表达式为I=U/R，即通过导体的电流与导体两端的电压成正比，与导体的电阻成反比。适用于金属导体和电解液。" },
  { q: "电阻的单位是？", options: ["欧姆", "安培", "伏特", "瓦特"], answer: 0, explanation: "电阻的单位是欧姆（Ω）。1欧姆表示当导体两端电压为1伏特时，通过导体的电流为1安培的电阻值。" },
  { q: "决定导体电阻大小的因素是？", options: ["材料、长度、横截面积、温度", "电压和电流", "电荷量和电压", "功率和电压"], answer: 0, explanation: "导体电阻由材料（电阻率）、长度、横截面积和温度决定。公式R=ρL/S，其中ρ为电阻率，L为长度，S为横截面积。温度升高通常使金属导体电阻增大。" },
  { q: "家庭电路的电压是？", options: ["220V", "110V", "380V", "36V"], answer: 0, explanation: "我国家庭电路电压为220V（交流电，频率50Hz）。美国等部分国家使用110V电压。380V是工业动力用电的线电压。36V以下为安全电压。" },
  { q: "发现电磁感应现象的科学家是？", options: ["法拉第", "奥斯特", "安培", "伏特"], answer: 0, explanation: "英国科学家法拉第于1831年发现了电磁感应现象，即变化的磁场可以产生感应电流。这一发现是发电机的工作原理基础，标志着电气时代的到来。" },
  { q: "奥斯特实验证明了？", options: ["电流周围存在磁场", "磁场可以产生电流", "电荷之间存在作用力", "磁场对电流有力的作用"], answer: 0, explanation: "丹麦物理学家奥斯特在1820年通过实验发现通电导线旁的磁针偏转，证明了电流周围存在磁场，即电可以生磁。这是电磁学的重大发现。" },
  { q: "发电机的工作原理是？", options: ["电磁感应现象", "电流的磁效应", "电流的热效应", "电流的化学效应"], answer: 0, explanation: "发电机利用电磁感应原理工作，通过转动线圈在磁场中切割磁感线产生感应电动势，将机械能转化为电能。" },
  { q: "电动机的工作原理是？", options: ["通电线圈在磁场中受力转动", "电磁感应现象", "电流的磁效应", "电流的热效应"], answer: 0, explanation: "电动机利用通电线圈在磁场中受到力的作用而转动的原理工作，将电能转化为机械能。电动机广泛用于各种机械设备中。" },
  { q: "变压器的工作原理是？", options: ["电磁感应", "电流的磁效应", "电流的热效应", "静电感应"], answer: 0, explanation: "变压器利用电磁感应原理工作，通过交变磁场在原副线圈中产生不同的感应电动势，实现电压的升高或降低。只能用于交流电。" },
  { q: "麦克斯韦方程组描述的是？", options: ["电磁场的基本规律", "物体运动规律", "热力学规律", "量子力学规律"], answer: 0, explanation: "麦克斯韦方程组是描述电磁场基本规律的四个方程，统一了电学和磁学，预言了电磁波的存在，并指出光是一种电磁波。是经典电磁学的核心。" },
  { q: "电磁波在真空中的传播速度是？", options: ["3×10⁸m/s", "3×10⁶m/s", "3×10¹⁰m/s", "3×10⁴m/s"], answer: 0, explanation: "电磁波在真空中传播速度等于光速c=3×10⁸m/s。麦克斯韦理论预言了电磁波的传播速度等于光速，揭示了光的电磁本质。" },
  { q: "下列关于电磁波谱的说法，正确的是？", options: ["无线电波的波长最长，γ射线的波长最短", "可见光波长最长", "红外线波长比无线电波长", "紫外线波长比X射线短"], answer: 0, explanation: "电磁波谱按波长从长到短依次为：无线电波、微波、红外线、可见光、紫外线、X射线、γ射线。无线电波波长最长、频率最低、能量最小；γ射线波长最短、频率最高、能量最大。" },
  { q: "下列不属于电磁波的是？", options: ["声波", "无线电波", "红外线", "X射线"], answer: 0, explanation: "声波是机械波，需要介质传播，不属于电磁波。无线电波、红外线、X射线都是电磁波，可以在真空中传播。" },
  { q: "安全用电的原则是？", options: ["不接触低压带电体，不靠近高压带电体", "可以接触低压带电体", "可以靠近高压带电体", "用湿手触摸开关"], answer: 0, explanation: "安全用电原则是不接触低压带电体（36V以上），不靠近高压带电体。不用湿手触摸电器和开关，不在电线上晾晒衣物，不损坏绝缘层。" },
  { q: "三孔插座中间的孔连接的是？", options: ["地线", "零线", "火线", "中性线"], answer: 0, explanation: "三孔插座中间的孔连接地线（PE线），左右两孔分别接零线（N线）和火线（L线）。家用电器使用三脚插头可将金属外壳接地，防止漏电时触电。" },
  { q: "磁感线的外部方向是？", options: ["从N极出发回到S极", "从S极出发回到N极", "从N极出发到无限远", "无固定方向"], answer: 0, explanation: "磁感线是描述磁场的假想曲线，在磁体外部从N极出发回到S极，在磁体内部从S极到N极，形成闭合曲线。磁感线密处磁场强，疏处磁场弱。" },

  // 光学（15题）
  { q: "光在真空中的传播速度是？", options: ["3×10⁸m/s", "3×10⁶m/s", "3×10¹⁰m/s", "3×10⁵m/s"], answer: 0, explanation: "光在真空中的传播速度c≈3×10⁸m/s（精确值为299792458m/s），这是宇宙中信息传播的最高速度。光在其他介质中传播速度小于此值。" },
  { q: "光的反射定律的内容是？", options: ["反射角等于入射角，反射光线、入射光线和法线在同一平面内", "反射角大于入射角", "反射角小于入射角", "反射光线与入射光线方向相同"], answer: 0, explanation: "光的反射定律：反射光线、入射光线和法线在同一平面内，反射光线和入射光线分居法线两侧，反射角等于入射角。" },
  { q: "光的折射现象是？", options: ["光从一种介质进入另一种介质时传播方向发生改变", "光被弹回原介质", "光绕过障碍物", "光分解为多种颜色"], answer: 0, explanation: "光从一种介质斜射入另一种介质时，传播方向发生改变的现象叫折射。折射是由于光在不同介质中传播速度不同造成的。" },
  { q: "白光通过三棱镜后分解成的七色光是？", options: ["红、橙、黄、绿、蓝、靛、紫", "红、黄、蓝、绿、紫、白、黑", "红、橙、黄、绿、青、蓝、紫", "红、黄、蓝、绿、青、紫、白"], answer: 0, explanation: "白光通过三棱镜后分解为红、橙、黄、绿、蓝、靛、紫七色光，这是光的色散现象，说明白光由多种色光组成。红光偏折最小，紫光偏折最大。" },
  { q: "下列关于光的干涉的说法，正确的是？", options: ["两束相干光波叠加产生明暗相间条纹", "光绕过障碍物的现象", "光分解为多种颜色", "光被弹回原介质"], answer: 0, explanation: "光的干涉是两束相干光波叠加后在空间形成明暗相间条纹的现象。杨氏双缝干涉实验证明了光的波动性。薄膜干涉如肥皂泡上的彩色花纹。" },
  { q: "光的衍射现象说明？", options: ["光能绕过障碍物传播", "光沿直线传播", "光不能绕过障碍物", "光只有粒子性"], answer: 0, explanation: "光的衍射是光绕过障碍物或通过狭缝偏离直线传播的现象。衍射现象说明光具有波动性。当障碍物或狭缝尺寸与光波长相近时衍射现象明显。" },
  { q: "首先提出光的波粒二象性的科学家是？", options: ["爱因斯坦", "牛顿", "惠更斯", "麦克斯韦"], answer: 0, explanation: "爱因斯坦在解释光电效应时提出光量子（光子）假说，揭示了光的粒子性。光的波动性由惠更斯等人提出。光既具有波动性又具有粒子性，称为波粒二象性。" },
  { q: "光电效应现象说明光具有？", options: ["粒子性", "波动性", "只有波动性", "电磁性"], answer: 0, explanation: "光电效应（金属在光照射下发射电子的现象）说明光具有粒子性。爱因斯坦用量子理论成功解释了光电效应，并获得1921年诺贝尔物理学奖。" },
  { q: "下列光学仪器中，利用光的折射原理的是？", options: ["放大镜", "平面镜", "潜望镜", "万花筒"], answer: 0, explanation: "放大镜是凸透镜，利用光的折射原理使物体成放大的虚像。平面镜、潜望镜、万花筒利用光的反射原理。" },
  { q: "人眼看近处物体时，晶状体会？", options: ["变厚，焦距变短", "变薄，焦距变长", "不变", "变厚，焦距变长"], answer: 0, explanation: "人眼看近处物体时，睫状肌收缩使晶状体变厚，焦距变短，使近处物体的像仍落在视网膜上。看远处物体时晶状体变薄，焦距变长。" },
  { q: "近视眼应佩戴哪种透镜矫正？", options: ["凹透镜", "凸透镜", "平光镜", "柱面透镜"], answer: 0, explanation: "近视眼由于晶状体过厚或眼球前后径过长，远处物体成像在视网膜前，需佩戴凹透镜（发散光线）矫正。远视眼则佩戴凸透镜矫正。" },
  { q: "远视眼应佩戴哪种透镜矫正？", options: ["凸透镜", "凹透镜", "平光镜", "柱面透镜"], answer: 0, explanation: "远视眼由于晶状体过薄或眼球前后径过短，近处物体成像在视网膜后，需佩戴凸透镜（会聚光线）矫正。" },
  { q: "海市蜃楼现象是由什么引起的？", options: ["光的折射和全反射", "光的反射", "光的直线传播", "光的干涉"], answer: 0, explanation: "海市蜃楼是由于空气温度不均匀导致空气密度不同，光在不同密度空气层中发生折射和全反射，使远处物体的像出现在半空中或地面以下。" },
  { q: "彩虹的形成原因是？", options: ["光的色散", "光的反射", "光的干涉", "光的衍射"], answer: 0, explanation: "彩虹是阳光照射到空气中的水滴时，经过折射、色散和反射形成的。水滴相当于小棱镜，将白光分解成七色光，形成彩虹。" },
  { q: "光的三原色是？", options: ["红、绿、蓝", "红、黄、蓝", "红、绿、黄", "青、品红、黄"], answer: 0, explanation: "光的三原色是红、绿、蓝（RGB）。三种色光等量混合得到白光。颜料的三原色是青、品红、黄（CMY），等量混合得到黑色。" },

  // 声学（15题）
  { q: "声音在空气中的传播速度约为？", options: ["340m/s", "3×10⁸m/s", "1500m/s", "5000m/s"], answer: 0, explanation: "声音在15°C空气中的传播速度约为340m/s。声音在液体中传播更快（水中约1500m/s），在固体中最快（钢铁中约5000m/s）。真空不能传声。" },
  { q: "声音的产生原因是？", options: ["物体振动", "物体静止", "光的传播", "电磁波"], answer: 0, explanation: "声音由物体振动产生，通过介质（气体、液体、固体）以声波形式传播。振动停止，发声也停止。真空不能传声。" },
  { q: "人耳能听到的声音频率范围是？", options: ["20Hz至20000Hz", "0Hz至1000Hz", "20000Hz以上", "20Hz以下"], answer: 0, explanation: "人耳能听到的声音频率范围为20Hz~20000Hz。低于20Hz的声波称为次声波，高于20000Hz的声波称为超声波。" },
  { q: "超声波的频率范围是？", options: ["高于20000Hz", "低于20Hz", "20Hz至20000Hz", "高于200000Hz"], answer: 0, explanation: "超声波是频率高于20000Hz的声波，人耳听不到。超声波方向性好、穿透力强，广泛应用于医疗（B超）、工业探伤、声呐等。" },
  { q: "次声波的频率范围是？", options: ["低于20Hz", "高于20000Hz", "20Hz至20000Hz", "高于2000Hz"], answer: 0, explanation: "次声波是频率低于20Hz的声波，人耳听不到。次声波传播距离远、穿透力强。地震、海啸等自然灾害会产生次声波，可用于灾害预警。" },
  { q: "多普勒效应描述的是？", options: ["波源与观察者相对运动时观察到的频率变化", "声波在介质中的传播速度", "声波的反射现象", "声波的干涉现象"], answer: 0, explanation: "多普勒效应指当波源与观察者有相对运动时，观察者接收到的频率与波源频率不同的现象。如救护车驶近时声音变高、远离时变低。" },
  { q: "下列关于声音的说法，正确的是？", options: ["声音不能在真空中传播", "声音能在真空中传播", "声音只能在气体中传播", "声音传播不需要介质"], answer: 0, explanation: "声音是机械波，传播需要介质，不能在真空中传播。声音可以在气体、液体和固体中传播，固体中传播最快。" },
  { q: "音调的高低取决于？", options: ["声波的频率", "声波的振幅", "声波的传播速度", "声波的波形"], answer: 0, explanation: "音调高低取决于声波频率，频率越高音调越高。响度大小取决于振幅，振幅越大响度越大。音色取决于发声体的材料和结构。" },
  { q: "响度的大小取决于？", options: ["声波的振幅", "声波的频率", "声波的传播速度", "声波的波长"], answer: 0, explanation: "响度（声音大小）取决于声波振幅，振幅越大响度越大。响度的单位是分贝（dB）。正常交谈声约60分贝，长期处于85分贝以上环境会损伤听力。" },
  { q: "音色取决于？", options: ["发声体的材料和结构", "声波振幅", "声波频率", "声波传播速度"], answer: 0, explanation: "音色取决于发声体的材料和结构，不同乐器演奏同一音调的声音可被区分就是由于音色不同。音色由声波的波形决定。" },
  { q: "B超检查利用的是？", options: ["超声波", "次声波", "电磁波", "X射线"], answer: 0, explanation: "B超（B型超声波）利用超声波进行医学检查。超声波对人体无害、穿透力强，能实时成像，广泛用于妇产科、心脏等检查。" },
  { q: "蝙蝠夜间飞行利用的是？", options: ["超声波回声定位", "红外线感应", "电磁感应", "可见光"], answer: 0, explanation: "蝙蝠利用超声波回声定位导航和捕食。蝙蝠发出超声波，根据回波的时间差和频率变化判断障碍物和猎物的位置、大小和运动速度。" },
  { q: "声呐系统利用的原理是？", options: ["超声波回声定位", "电磁波反射", "光的折射", "放射性探测"], answer: 0, explanation: "声呐（SONAR）利用超声波在水中传播和反射的原理进行水下探测，用于测距、导航、探测潜艇和鱼群等。声呐分为主动式和被动式两种。" },
  { q: "噪声污染的控制方法不包括？", options: ["增加声源功率", "在声源处减弱", "在传播过程中减弱", "在人耳处减弱"], answer: 0, explanation: "控制噪声的三种途径：在声源处减弱（如安装消声器）、在传播过程中减弱（如隔音墙、植树造林）、在人耳处减弱（如戴耳塞）。增加声源功率会增加噪声。" },
  { q: "回声现象说明声音具有？", options: ["反射现象", "折射现象", "干涉现象", "衍射现象"], answer: 0, explanation: "回声是声音遇到障碍物反射回来再被听到的现象。人耳要区分原声和回声，时间差需大于0.1秒，对应障碍物距离至少17米。" },

  // 原子物理（15题）
  { q: "提出原子核式结构模型的科学家是？", options: ["卢瑟福", "汤姆逊", "玻尔", "爱因斯坦"], answer: 0, explanation: "卢瑟福通过α粒子散射实验（金箔实验）提出了原子的核式结构模型：原子由带正电的原子核和核外电子组成，原子核体积很小但集中了几乎全部质量。" },
  { q: "发现电子的科学家是？", options: ["汤姆逊", "卢瑟福", "玻尔", "居里夫人"], answer: 0, explanation: "汤姆逊通过阴极射线实验发现了电子，证明电子是原子的组成部分。电子的发现打破了原子不可分的传统观念。" },
  { q: "原子的组成是？", options: ["原子核和核外电子", "质子和中子", "电子和光子", "原子核和光子"], answer: 0, explanation: "原子由带正电的原子核和带负电的核外电子组成。原子核由质子（带正电）和中子（不带电）组成。整个原子呈电中性。" },
  { q: "α射线实际上是？", options: ["氦原子核", "电子流", "电磁波", "中子流"], answer: 0, explanation: "α射线是带正电的氦原子核（He²⁺），由两个质子和两个中子组成。α射线电离能力强，穿透能力弱，一张纸就能挡住。" },
  { q: "β射线实际上是？", options: ["电子流", "氦原子核", "电磁波", "质子流"], answer: 0, explanation: "β射线是高速电子流，带负电。β射线穿透能力比α射线强，可被铝板挡住。β衰变是原子核内中子转变为质子和电子的过程。" },
  { q: "γ射线实际上是？", options: ["高频电磁波", "电子流", "氦原子核", "中子流"], answer: 0, explanation: "γ射线是波长极短的高频电磁波，不带电。γ射线穿透能力最强，需要厚铅板或混凝土才能阻挡。γ射线常伴随α或β衰变产生。" },
  { q: "核裂变是指？", options: ["重原子核分裂成两个较轻的原子核", "轻原子核聚合成较重的原子核", "原子核放出电子", "原子核放出电磁波"], answer: 0, explanation: "核裂变是重原子核（如铀-235、钚-239）分裂成两个较轻原子核的过程，同时释放大量能量和中子。核电站和原子弹利用核裂变原理。" },
  { q: "核聚变是指？", options: ["轻原子核聚合成较重的原子核", "重原子核分裂成较轻的原子核", "原子核放出电子", "原子核放出光子"], answer: 0, explanation: "核聚变是轻原子核（如氢的同位素氘和氚）聚合成较重原子核（氦）的过程，释放巨大能量。太阳发光发热的原理就是核聚变，氢弹也利用核聚变。" },
  { q: "核电站利用的核反应是？", options: ["可控核裂变", "可控核聚变", "不可控核裂变", "核衰变"], answer: 0, explanation: "核电站利用可控核裂变反应释放的能量发电，常用核燃料为铀-235。反应堆中的控制棒吸收中子控制反应速度。核聚变目前尚未实现可控利用。" },
  { q: "太阳发光发热的能量来源是？", options: ["核聚变", "核裂变", "化学燃烧", "引力收缩"], answer: 0, explanation: "太阳能量来源于核心的核聚变反应，氢聚变成氦释放巨大能量。太阳每秒约消耗6亿吨氢，预计还可燃烧约50亿年。" },
  { q: "发现放射性的科学家是？", options: ["贝克勒尔", "卢瑟福", "汤姆逊", "玻尔"], answer: 0, explanation: "法国科学家贝克勒尔于1896年首次发现铀盐具有放射性，能自发发出穿透性射线。这一发现开创了原子核物理学的研究。" },
  { q: "下列关于半衰期的说法，正确的是？", options: ["放射性元素的半衰期不随外界条件改变", "半衰期与温度有关", "半衰期与压力有关", "半衰期可以人为改变"], answer: 0, explanation: "半衰期是放射性元素的原子核有半数发生衰变所需的时间，是元素的固有特性，不随温度、压力、化学状态等外界条件改变。" },
  { q: "爱因斯坦质能方程是？", options: ["E=mc²", "E=mc", "E=mc³", "E=m/c²"], answer: 0, explanation: "爱因斯坦质能方程E=mc²揭示了质量和能量的等价关系，其中E为能量，m为质量，c为光速。核反应释放的巨大能量来源于质量亏损。" },
  { q: "下列关于原子能级的说法，正确的是？", options: ["原子从高能级跃迁到低能级时放出光子", "原子从低能级跃迁到高能级时放出光子", "原子能级是连续的", "原子跃迁不涉及能量变化"], answer: 0, explanation: "原子从高能级跃迁到低能级时放出光子（自发辐射），从低能级跃迁到高能级时吸收光子。能级是不连续的（量子化的），放出或吸收的光子能量等于两能级之差。" },
  { q: "氢弹利用的核反应是？", options: ["核聚变", "核裂变", "核衰变", "化学爆炸"], answer: 0, explanation: "氢弹利用核聚变反应（氢的同位素氘和氚聚合成氦）释放巨大能量。氢弹威力远大于原子弹。核聚变需要极高温度和压力才能发生，氢弹用原子弹引爆产生所需条件。" },

  // 量子力学基础（10题）
  { q: "量子力学的奠基人之一是？", options: ["普朗克", "牛顿", "伽利略", "法拉第"], answer: 0, explanation: "普朗克于1900年提出能量量子假说，认为能量是不连续的，以量子形式存在，标志着量子力学的诞生。普朗克因此获得1918年诺贝尔物理学奖。" },
  { q: "海森堡不确定性原理的内容是？", options: ["不可能同时精确测定粒子的位置和动量", "能量和质量可以互换", "光速是恒定的", "熵总是增加的"], answer: 0, explanation: "海森堡不确定性原理指出，不可能同时精确测定粒子的位置和动量。位置测定越精确，动量测定越不精确，反之亦然。这是量子力学的基本原理之一。" },
  { q: "波函数的物理意义是？", options: ["描述粒子在某位置出现的概率", "描述粒子的确定位置", "描述粒子的确定速度", "描述粒子的能量"], answer: 0, explanation: "波函数的模的平方表示粒子在某位置出现的概率密度（玻恩诠释）。波函数本身没有直接的物理意义，但其平方给出了粒子出现的概率分布。" },
  { q: "量子力学中粒子的状态由什么描述？", options: ["波函数", "位置坐标", "速度向量", "质量"], answer: 0, explanation: "量子力学中粒子的状态由波函数（ψ）描述。波函数包含了粒子的一切信息，通过薛定谔方程可以求解波函数随时间的演化。" },
  { q: "薛定谔方程描述的是？", options: ["波函数随时间的演化规律", "粒子的运动轨迹", "粒子的能量守恒", "粒子的动量变化"], answer: 0, explanation: "薛定谔方程是量子力学的基本方程，描述了波函数随时间的演化规律。它相当于经典力学中的牛顿运动方程，是量子力学的核心方程。" },
  { q: "量子叠加态是指？", options: ["一个量子系统可以同时处于多个状态的叠加", "粒子可以同时出现在不同位置", "粒子可以无限分裂", "粒子可以消失"], answer: 0, explanation: "量子叠加态是指一个量子系统可以同时处于多个状态的线性叠加。薛定谔的猫思想实验就是叠加态的著名例子：在观测前，猫处于死和活的叠加态。" },
  { q: "量子纠缠是指？", options: ["两个或多个粒子的量子状态相互关联", "粒子之间有物理连接", "粒子相互排斥", "粒子相互吸引"], answer: 0, explanation: "量子纠缠是指两个或多个粒子的量子状态相互关联，无论相距多远，对其中一个粒子的测量会瞬间影响另一个粒子的状态。爱因斯坦称之为鬼魅般的超距作用。" },
  { q: "量子隧穿效应是指？", options: ["粒子能穿过经典物理认为不可能穿过的势垒", "粒子能穿透任何物体", "粒子可以消失", "粒子可以无限加速"], answer: 0, explanation: "量子隧穿效应是指粒子有一定概率穿过经典物理认为不可能穿过的势垒。这是量子力学特有的现象，在半导体、扫描隧道显微镜等中有重要应用。" },
  { q: "波粒二象性首先由谁提出？", options: ["德布罗意", "爱因斯坦", "普朗克", "海森堡"], answer: 0, explanation: "法国物理学家德布罗意于1924年提出物质波假说，认为一切实物粒子都具有波粒二象性。这一假说后来被电子衍射实验证实。德布罗意因此获得1929年诺贝尔物理学奖。" },
  { q: "量子计算利用的量子特性不包括？", options: ["万有引力", "量子叠加", "量子纠缠", "量子干涉"], answer: 0, explanation: "量子计算利用量子叠加、量子纠缠和量子干涉等量子力学特性进行计算。量子比特可以同时处于0和1的叠加态，使量子计算在某些问题上具有指数级加速优势。万有引力与量子计算无关。" },

  // ==================== 化学（100题）====================
  // 元素周期表（15题）
  { q: "元素周期表的编制者是？", options: ["门捷列夫", "道尔顿", "拉瓦锡", "阿伏伽德罗"], answer: 0, explanation: "俄国化学家门捷列夫于1869年编制了第一张元素周期表，将元素按原子量排列，发现了元素性质的周期性规律。他还在表中预留空位，预言了后来发现的元素。" },
  { q: "元素周期表中共有多少个周期？", options: ["7个", "5个", "6个", "8个"], answer: 0, explanation: "元素周期表共有7个周期。第1~3周期为短周期，第4~7周期为长周期。第7周期为不完全周期。每一周期从左到右原子序数递增。" },
  { q: "元素周期表中共有多少个族？", options: ["18个", "16个", "8个", "20个"], answer: 0, explanation: "元素周期表共有18个纵列，即18个族。其中7个主族（IA~VIIA）、7个副族（IB~VIIB）、第VIII族（3列）和0族（稀有气体）。同族元素性质相似。" },
  { q: "下列元素中属于碱金属的是？", options: ["钠", "镁", "铝", "铁"], answer: 0, explanation: "钠属于碱金属（IA族），性质活泼，能与水剧烈反应生成氢气。碱金属包括锂、钠、钾、铷、铯、钫，金属性从上到下逐渐增强。" },
  { q: "下列元素中属于卤素的是？", options: ["氟", "氧", "氮", "硫"], answer: 0, explanation: "氟属于卤素（VIIA族）。卤素包括氟、氯、溴、碘、砹，是非金属性最强的元素族。卤素单质与水、金属都能反应，氧化性从上到下减弱。" },
  { q: "稀有气体元素位于元素周期表的？", options: ["第0族（第18族）", "第IA族", "第VIIA族", "第VIII族"], answer: 0, explanation: "稀有气体（惰性气体）位于元素周期表第0族（第18族），包括氦、氖、氩、氪、氙、氡。稀有气体最外层电子已达稳定结构（8电子或2电子），化学性质极不活泼。" },
  { q: "元素周期表中原子序数等于？", options: ["原子的质子数", "原子的中子数", "原子的电子数", "原子的质量数"], answer: 0, explanation: "元素的原子序数等于原子核内的质子数，也等于核外电子数（中性原子）。原子序数决定了元素的种类。例如碳的原子序数为6，有6个质子和6个电子。" },
  { q: "同位素是指？", options: ["质子数相同、中子数不同的原子", "中子数相同、质子数不同的原子", "质子数和中子数都相同", "电子数不同的原子"], answer: 0, explanation: "同位素是质子数（原子序数）相同但中子数不同的同种元素的不同原子。如氢有三种同位素：氕、氘、氚，化学性质相似但物理性质不同。" },
  { q: "下列元素中，地壳中含量最多的是？", options: ["氧", "硅", "铝", "铁"], answer: 0, explanation: "地壳中含量最多的元素是氧（约46.6%），其次是硅（约27.7%）、铝（约8.1%）、铁（约5%）。地壳中含量最多的金属元素是铝。" },
  { q: "元素周期表中从左到右，元素的金属性如何变化？", options: ["逐渐减弱", "逐渐增强", "不变", "先增强后减弱"], answer: 0, explanation: "同一周期从左到右，元素的金属性逐渐减弱，非金属性逐渐增强。因为从左到右核电荷数增加，原子半径减小，原子核对最外层电子吸引力增强，越难失去电子。" },
  { q: "元素周期表中从上到下，同一主族元素的非金属性如何变化？", options: ["逐渐减弱", "逐渐增强", "不变", "先减弱后增强"], answer: 0, explanation: "同一主族从上到下，元素的非金属性逐渐减弱，金属性逐渐增强。因为原子半径增大，原子核对最外层电子吸引力减弱，更容易失去电子。" },
  { q: "下列元素中属于过渡金属的是？", options: ["铁", "钠", "钙", "铝"], answer: 0, explanation: "铁属于过渡金属（d区元素），位于第VIII族。过渡金属具有多种氧化态，化合物常带有颜色，常用作催化剂。钠、钙为s区元素，铝为p区元素。" },
  { q: "最外层电子数决定元素的？", options: ["化学性质", "原子量", "中子数", "同位素种类"], answer: 0, explanation: "最外层电子数决定元素的化学性质。最外层电子数越少越容易失去电子，金属性越强；最外层电子数越多（接近8）越容易得到电子，非金属性越强。" },
  { q: "下列关于元素周期律的说法，正确的是？", options: ["元素性质随原子序数递增呈周期性变化", "元素性质随原子量递增线性变化", "元素性质不随原子序数变化", "元素性质随机变化"], answer: 0, explanation: "元素周期律指元素的性质随原子序数递增而呈周期性变化的规律。这是由于元素原子的电子层结构呈周期性变化。门捷列夫首先发现了这一规律。" },
  { q: "下列元素中，不属于主族元素的是？", options: ["铁", "钠", "氯", "碳"], answer: 0, explanation: "铁属于过渡金属（第VIII族），不是主族元素。钠（IA族）、氯（VIIA族）、碳（IVA族）都是主族元素。主族元素包括s区和p区元素。" },

  // 化学键（15题）
  { q: "化学键的基本类型不包括？", options: ["分子间作用力", "离子键", "共价键", "金属键"], answer: 0, explanation: "化学键的基本类型包括离子键、共价键和金属键。分子间作用力（范德华力）不是化学键，其作用力远弱于化学键。氢键是一种较强的分子间作用力。" },
  { q: "离子键是由什么形成的？", options: ["阴、阳离子之间的静电作用", "原子间共用电子对", "金属原子间的自由电子", "分子间的引力"], answer: 0, explanation: "离子键是阴阳离子之间的静电作用，通常由活泼金属和活泼非金属之间通过电子转移形成。如NaCl中Na+和Cl-之间的化学键就是离子键。" },
  { q: "共价键是由什么形成的？", options: ["原子间共用电子对", "阴阳离子的静电作用", "金属原子间的自由电子", "分子间引力"], answer: 0, explanation: "共价键是原子间通过共用电子对形成的化学键，通常由非金属元素之间形成。如H2O中氢原子和氧原子之间的键就是共价键。" },
  { q: "下列化合物中，含有离子键的是？", options: ["NaCl", "H2O", "CO2", "CH4"], answer: 0, explanation: "NaCl含有离子键，由钠离子（Na+）和氯离子（Cl-）之间静电作用形成。H2O、CO2、CH4中的化学键都是共价键。" },
  { q: "下列化合物中，只含共价键的是？", options: ["H2O", "NaCl", "KOH", "MgO"], answer: 0, explanation: "H2O只含共价键（氢氧共价键）。NaCl和MgO只含离子键。KOH既含离子键（K+和OH-之间）又含共价键（O和H之间）。" },
  { q: "金属键的本质是？", options: ["金属阳离子与自由电子之间的作用", "阴阳离子间的静电作用", "原子间共用电子对", "分子间引力"], answer: 0, explanation: "金属键是金属阳离子与自由电子之间的强烈相互作用。自由电子在金属中自由移动，将金属阳离子粘合在一起。金属键解释了金属的导电性、导热性和延展性。" },
  { q: "下列物质的化学键类型相同的是？", options: ["NaCl和KBr", "NaCl和HCl", "HCl和NaOH", "CO2和Na2O"], answer: 0, explanation: "NaCl和KBr都只含离子键。NaCl含离子键，HCl含共价键。NaOH既含离子键又含共价键。CO2含共价键，Na2O含离子键。" },
  { q: "氢键是一种？", options: ["较强的分子间作用力", "化学键", "离子键", "金属键"], answer: 0, explanation: "氢键是一种较强的分子间作用力，不是化学键。氢键存在于与高电负性原子（N、O、F）相连的氢原子和另一个高电负性原子之间。氢键解释了水的反常高沸点。" },
  { q: "下列关于离子化合物的说法，正确的是？", options: ["由离子键形成的化合物", "由共价键形成的化合物", "由金属键形成的化合物", "不含化学键的物质"], answer: 0, explanation: "离子化合物是由离子键形成的化合物，如NaCl、MgO等。离子化合物在固态时不导电，溶于水或熔融状态下能导电。" },
  { q: "下列关于共价化合物的说法，正确的是？", options: ["由共价键形成的化合物", "由离子键形成的化合物", "在熔融状态下能导电", "一定不含离子键"], answer: 0, explanation: "共价化合物是由共价键形成的化合物，如H2O、CO2等。共价化合物在熔融状态下一般不导电（因为没有自由移动的离子）。" },
  { q: "下列物质的化学键中，既有离子键又有共价键的是？", options: ["NaOH", "NaCl", "H2O", "O2"], answer: 0, explanation: "NaOH中Na+和OH-之间是离子键，OH-中O和H之间是共价键，既有离子键又有共价键。NaCl只含离子键，H2O和O2只含共价键。" },
  { q: "非极性共价键存在于？", options: ["同种元素原子之间", "不同种元素原子之间", "金属原子之间", "阴阳离子之间"], answer: 0, explanation: "非极性共价键存在于同种元素的原子之间，共用电子对不偏移，如O=O、H-H等。不同种元素原子间的共价键为极性共价键，共用电子对偏向电负性大的原子。" },
  { q: "下列分子中，含有非极性键的是？", options: ["O2", "HCl", "H2O", "NaCl"], answer: 0, explanation: "O2分子中的O=O键是非极性共价键（同种元素原子间）。HCl中H-Cl是极性共价键。H2O中O-H是极性共价键。NaCl是离子键。" },
  { q: "原子的稳定结构通常指最外层有？", options: ["8个电子（第一层为2个）", "4个电子", "6个电子", "2个电子"], answer: 0, explanation: "原子的稳定结构通常指最外层有8个电子（第一电子层为2个），即稀有气体的电子层结构。化学键的形成就是为了使原子达到稳定结构（8电子结构）。" },
  { q: "下列关于电子式的说法，正确的是？", options: ["电子式用小黑点表示原子最外层电子", "电子式表示所有电子", "电子式只用于离子化合物", "电子式不表示化学键"], answer: 0, explanation: "电子式用小黑点（或×）表示原子或离子的最外层电子，用于表示化学键的形成过程和物质结构。如NaCl的电子式为Na+[:Cl:]-。" },

  // 化学反应（15题）
  { q: "化学反应的基本类型不包括？", options: ["核反应", "化合反应", "分解反应", "置换反应"], answer: 0, explanation: "化学反应的四种基本类型为化合反应、分解反应、置换反应和复分解反应。核反应不属于化学反应，因为涉及原子核的变化，而非核外电子的重组。" },
  { q: "化合反应的特点是？", options: ["两种或两种以上物质生成一种新物质", "一种物质生成两种或以上物质", "单质与化合物反应", "两种化合物交换成分"], answer: 0, explanation: "化合反应是两种或两种以上的物质生成一种新物质的反应，通式为A+B→AB。如2H2+O2→2H2O。" },
  { q: "分解反应的特点是？", options: ["一种物质生成两种或两种以上新物质", "两种物质生成一种物质", "单质与化合物反应", "两种化合物交换成分"], answer: 0, explanation: "分解反应是一种物质生成两种或两种以上新物质的反应，通式为AB→A+B。如2H2O→2H2+O2（电解水）。" },
  { q: "置换反应的特点是？", options: ["单质与化合物反应生成新单质和新化合物", "两种化合物交换成分", "两种物质生成一种物质", "一种物质分解"], answer: 0, explanation: "置换反应是单质与化合物反应生成新单质和新化合物的反应，通式为A+BC→AC+B。如Fe+CuSO4→FeSO4+Cu。" },
  { q: "复分解反应的特点是？", options: ["两种化合物交换成分生成两种新化合物", "两种物质生成一种物质", "一种物质分解", "单质与化合物反应"], answer: 0, explanation: "复分解反应是两种化合物互相交换成分生成两种新化合物的反应，通式为AB+CD→AD+CB。如NaOH+HCl→NaCl+H2O（酸碱中和）。" },
  { q: "氧化还原反应的本质是？", options: ["电子的转移", "能量的变化", "物质状态的改变", "颜色的变化"], answer: 0, explanation: "氧化还原反应的本质是电子的转移（得失或偏移）。失电子被氧化（化合价升高），得电子被还原（化合价降低）。氧化和还原同时发生。" },
  { q: "氧化反应是指？", options: ["物质失去电子（化合价升高）", "物质得到电子（化合价降低）", "物质与氧反应", "物质分解"], answer: 0, explanation: "氧化反应是物质失去电子（化合价升高）的过程。早期定义是与氧化合，后来扩展为失电子的过程。氧化和还原总是同时发生的。" },
  { q: "还原反应是指？", options: ["物质得到电子（化合价降低）", "物质失去电子（化合价升高）", "物质失去氧", "物质分解"], answer: 0, explanation: "还原反应是物质得到电子（化合价降低）的过程。氧化剂被还原，还原剂被氧化。氧化剂和还原剂是反应物，不是生成物。" },
  { q: "氧化剂在反应中？", options: ["得到电子被还原", "失去电子被氧化", "不参与电子转移", "催化反应"], answer: 0, explanation: "氧化剂在反应中得到电子被还原，自身化合价降低。氧化剂使其他物质氧化。常见的氧化剂有O2、KMnO4、HNO3等。" },
  { q: "还原剂在反应中？", options: ["失去电子被氧化", "得到电子被还原", "不参与电子转移", "催化反应"], answer: 0, explanation: "还原剂在反应中失去电子被氧化，自身化合价升高。还原剂使其他物质还原。常见的还原剂有H2、C、CO、活泼金属等。" },
  { q: "下列反应中属于氧化还原反应的是？", options: ["2H2+O2→2H2O", "NaOH+HCl→NaCl+H2O", "CaCO3→CaO+CO2", "AgNO3+NaCl→AgCl+NaNO3"], answer: 0, explanation: "2H2+O2→2H2O中氢的化合价从0变为+1，氧从0变为-2，有化合价变化，属于氧化还原反应。其余三个反应化合价不变，不属于氧化还原反应。" },
  { q: "催化剂的作用是？", options: ["改变反应速率但本身质量和化学性质不变", "增加反应物的量", "改变反应产物", "降低反应温度"], answer: 0, explanation: "催化剂能改变（加快或减慢）化学反应速率，但反应前后本身的质量和化学性质不发生变化。催化剂不改变反应的平衡位置，只改变达到平衡的速率。" },
  { q: "化学方程式配平的依据是？", options: ["质量守恒定律", "能量守恒定律", "动量守恒定律", "电荷守恒定律"], answer: 0, explanation: "化学方程式配平依据质量守恒定律，即反应前后各元素原子种类和数目不变。通过配平使反应物和生成物中各元素原子数目相等。" },
  { q: "下列关于放热反应和吸热反应的说法，正确的是？", options: ["放热反应释放能量，吸热反应吸收能量", "放热反应吸收能量", "吸热反应释放能量", "所有反应都放热"], answer: 0, explanation: "放热反应释放能量（如燃烧、中和反应），反应物总能量大于生成物总能量。吸热反应吸收能量（如分解反应），反应物总能量小于生成物总能量。能量以热能形式表现。" },
  { q: "燃烧需要满足的三个条件是？", options: ["可燃物、氧气（氧化剂）、温度达到着火点", "可燃物、光、热", "可燃物、水、空气", "可燃物、压力、温度"], answer: 0, explanation: "燃烧的三个条件：有可燃物、有氧气（或氧化剂）、温度达到着火点。三者缺一不可。灭火原理就是消除这三个条件之一：隔离可燃物、隔绝氧气、降低温度。" },

  // 溶液（15题）
  { q: "溶液的基本特征是？", options: ["均一、稳定", "不均匀、不稳定", "有颜色", "透明无色"], answer: 0, explanation: "溶液的基本特征是均一（各部分性质相同）和稳定（长时间放置不分层）。溶液是混合物，由溶质和溶剂组成。溶液不一定无色（如CuSO4溶液为蓝色）。" },
  { q: "下列关于溶质和溶剂的说法，正确的是？", options: ["被溶解的物质叫溶质，能溶解其他物质的物质叫溶剂", "溶质是液体，溶剂是固体", "溶质和溶剂都是固体", "溶质是溶剂的一部分"], answer: 0, explanation: "被溶解的物质叫溶质，能溶解其他物质的物质叫溶剂。最常用的溶剂是水。碘酒中碘是溶质，酒精是溶剂。两种液体互溶时量少的为溶质。" },
  { q: "饱和溶液是指？", options: ["在一定温度下不能再溶解该溶质的溶液", "浓度很高的溶液", "有固体剩余的溶液", "所有溶液都是饱和溶液"], answer: 0, explanation: "饱和溶液是在一定温度下，在一定量溶剂中不能再溶解某种溶质的溶液。饱和与不饱和是相对的，改变温度或溶剂量可以相互转化。" },
  { q: "溶解度是指？", options: ["在一定温度下100g溶剂中达到饱和时溶解的溶质质量", "100g溶液中溶质的质量", "1L溶液中溶质的量", "溶质在溶剂中的体积比"], answer: 0, explanation: "固体溶解度是指在一定温度下，100g溶剂（通常是水）中达到饱和状态时所能溶解的溶质质量（单位g）。溶解度随温度变化而变化。" },
  { q: "气体溶解度随温度升高而？", options: ["减小", "增大", "不变", "先增大后减小"], answer: 0, explanation: "气体溶解度随温度升高而减小（如烧水时水中的气泡逸出），随压强增大而增大（如制碳酸饮料时加压溶入CO2）。" },
  { q: "pH=7的溶液呈？", options: ["中性", "酸性", "碱性", "强酸性"], answer: 0, explanation: "pH=7的溶液呈中性（常温下），如纯水。pH<7呈酸性，pH>7呈碱性。pH范围0~14，pH越小酸性越强，pH越大碱性越强。" },
  { q: "下列溶液pH值小于7的是？", options: ["食醋", "石灰水", "食盐水", "小苏打溶液"], answer: 0, explanation: "食醋含醋酸，pH<7呈酸性。石灰水（Ca(OH)2）pH>7呈碱性。食盐水pH≈7呈中性。小苏打（NaHCO3）溶液呈弱碱性。" },
  { q: "酸碱中和反应的产物是？", options: ["盐和水", "盐和气体", "水和气体", "盐和沉淀"], answer: 0, explanation: "酸碱中和反应产物是盐和水，如HCl+NaOH→NaCl+H2O。中和反应是复分解反应的一种特殊形式，实质是H+和OH-结合生成水。" },
  { q: "下列物质溶于水后溶液呈酸性的是？", options: ["CO2", "NaOH", "NaCl", "CaO"], answer: 0, explanation: "CO2溶于水生成碳酸（H2CO3），溶液呈酸性。NaOH溶于水呈强碱性。NaCl溶于水呈中性。CaO溶于水生成Ca(OH)2呈碱性。" },
  { q: "下列物质溶于水后溶液呈碱性的是？", options: ["Na2CO3", "HCl", "NaCl", "CO2"], answer: 0, explanation: "Na2CO3（纯碱）溶于水后，由于CO3 2-水解使溶液呈碱性。HCl溶于水呈酸性。NaCl溶于水呈中性。CO2溶于水呈酸性。" },
  { q: "质量分数为10%的NaCl溶液100g中含NaCl的质量为？", options: ["10g", "1g", "100g", "90g"], answer: 0, explanation: "质量分数=溶质质量/溶液质量×100%。100g 10%的NaCl溶液中含NaCl：100g×10%=10g，含水90g。" },
  { q: "将50g水加入50g 20%的NaCl溶液中，稀释后溶液的质量分数为？", options: ["10%", "20%", "40%", "5%"], answer: 0, explanation: "原溶液中NaCl质量=50g×20%=10g。加水后溶液总质量=50g+50g=100g。稀释后质量分数=10g/100g×100%=10%。" },
  { q: "下列关于溶液的说法，正确的是？", options: ["溶液都是混合物", "溶液都是纯净物", "溶液都是无色的", "溶液都是液体"], answer: 0, explanation: "溶液都是混合物，由溶质和溶剂组成。溶液可以有颜色（如CuSO4溶液蓝色）。溶液不一定是液体，合金是固体溶液，空气是气体溶液。" },
  { q: "下列物质中属于悬浊液的是？", options: ["泥水", "食盐水", "糖水", "碘酒"], answer: 0, explanation: "泥水是悬浊液（固体小颗粒悬浮在液体中），不稳定会沉降。食盐水、糖水是溶液。碘酒是溶液。溶液、悬浊液和乳浊液都是混合物。" },
  { q: "下列说法正确的是？", options: ["饱和溶液不一定是浓溶液，不饱和溶液不一定是稀溶液", "饱和溶液一定是浓溶液", "不饱和溶液一定是稀溶液", "浓溶液一定是饱和溶液"], answer: 0, explanation: "饱和与浓稀是不同概念。溶解度大的物质饱和溶液是浓溶液，但溶解度小的物质饱和溶液可能是稀溶液（如Ca(OH)2饱和溶液就很稀）。关键看是否达到最大溶解量。" },

  // 有机化学（15题）
  { q: "有机化合物的特点是？", options: ["大多含有碳元素", "都不含碳元素", "都是气体", "都是无机物"], answer: 0, explanation: "有机化合物（有机物）通常指含碳的化合物（但CO、CO2、碳酸盐等通常归为无机物）。有机物种类繁多，大多含C、H元素，也可含O、N、S、P等。" },
  { q: "最简单的有机物是？", options: ["甲烷", "乙烯", "乙炔", "甲醇"], answer: 0, explanation: "甲烷（CH4）是最简单的有机物，是天然气和沼气的主要成分。甲烷完全燃烧产生CO2和H2O，是清洁燃料。甲烷也是温室气体。" },
  { q: "下列物质中属于烃的是？", options: ["CH4", "CH3OH", "CH3COOH", "C2H5OH"], answer: 0, explanation: "烃是只含碳和氢两种元素的有机物。CH4（甲烷）是烃。CH3OH（甲醇）、C2H5OH（乙醇）、CH3COOH（醋酸）都含氧，不是烃。" },
  { q: "乙醇的化学式是？", options: ["C2H5OH", "CH3OH", "CH3COOH", "C2H6"], answer: 0, explanation: "乙醇（酒精）的化学式为C2H5OH。乙醇是可再生能源，可用作燃料、消毒剂（75%酒精）和溶剂。甲醇（CH3OH）有毒，不可饮用。" },
  { q: "下列关于甲烷的说法，不正确的是？", options: ["甲烷是无色无味的有毒气体", "甲烷是无色无味气体", "甲烷是天然气的主要成分", "甲烷完全燃烧生成CO2和H2O"], answer: 0, explanation: "甲烷是无色无味气体，没有毒，但有窒息性危险（在密闭空间中取代氧气）。甲烷是天然气和沼气的主要成分，完全燃烧生成CO2和H2O。" },
  { q: "下列关于乙烯的说法，正确的是？", options: ["乙烯是植物生长调节剂", "乙烯是固体", "乙烯不含碳元素", "乙烯不能燃烧"], answer: 0, explanation: "乙烯（C2H4）是一种植物生长调节剂，能催熟水果。乙烯是气体，含碳元素，能燃烧。乙烯也是重要的化工原料，用于制造聚乙烯塑料。" },
  { q: "下列属于高分子化合物的是？", options: ["聚乙烯", "乙醇", "乙酸", "甲烷"], answer: 0, explanation: "聚乙烯是高分子化合物（聚合物），由乙烯单体聚合而成，是常用的塑料。乙醇、乙酸、甲烷都是小分子化合物。" },
  { q: "淀粉属于下列哪类有机物？", options: ["糖类（碳水化合物）", "蛋白质", "脂质", "维生素"], answer: 0, explanation: "淀粉属于糖类（碳水化合物），化学式为(C6H10O5)n，是高分子化合物。淀粉在人体内消化为葡萄糖提供能量，是人体主要能量来源。" },
  { q: "蛋白质的基本组成单位是？", options: ["氨基酸", "葡萄糖", "脂肪酸", "核苷酸"], answer: 0, explanation: "蛋白质的基本组成单位是氨基酸。人体内有20种氨基酸，其中8种是必需氨基酸（人体不能自行合成，需从食物获取）。蛋白质是生命活动的物质基础。" },
  { q: "下列关于油脂的说法，正确的是？", options: ["油脂是人体重要的储能物质", "油脂是糖类", "油脂是蛋白质", "油脂是无机物"], answer: 0, explanation: "油脂是人体重要的储能物质，属于脂质。油脂由甘油和脂肪酸组成，是人体含量最多的储能物质。油脂在体内氧化分解释放能量。" },
  { q: "下列关于醋酸的说法，正确的是？", options: ["醋酸的化学式为CH3COOH", "醋酸是无机酸", "醋酸是强酸", "醋酸不含碳元素"], answer: 0, explanation: "醋酸（乙酸）化学式为CH3COOH，是有机弱酸，是食醋的主要成分（3%~5%）。醋酸有刺激性气味，溶于水呈酸性。" },
  { q: "塑料属于下列哪类物质？", options: ["合成高分子化合物", "天然高分子化合物", "无机物", "小分子化合物"], answer: 0, explanation: "塑料是合成高分子化合物（聚合物），由单体聚合而成。常见塑料有聚乙烯（PE）、聚氯乙烯（PVC）、聚丙烯（PP）等。塑料不易降解，会造成白色污染。" },
  { q: "下列关于聚氯乙烯（PVC）的说法，正确的是？", options: ["PVC燃烧会产生有毒气体", "PVC是天然材料", "PVC可以降解", "PVC不含氯元素"], answer: 0, explanation: "聚氯乙烯（PVC）燃烧会产生有毒的氯化氢气体。PVC是合成塑料，不易降解，不适合包装食品（可能释放有害物质）。PVC含氯元素。" },
  { q: "天然橡胶的主要成分是？", options: ["聚异戊二烯", "聚乙烯", "聚氯乙烯", "聚苯乙烯"], answer: 0, explanation: "天然橡胶的主要成分是聚异戊二烯，从橡胶树的胶乳中提取。合成橡胶（如丁苯橡胶、氯丁橡胶）具有更好的耐磨性、耐热性等性能，广泛应用于轮胎等制品。" },
  { q: "下列关于聚合反应的说法，正确的是？", options: ["单体通过化学键结合成高分子化合物的反应", "一种物质分解为多种物质的反应", "两种物质交换成分的反应", "单质与化合物反应"], answer: 0, explanation: "聚合反应是单体（小分子）通过化学键结合成高分子化合物的反应。如乙烯聚合成聚乙烯：nC2H4→(C2H4)n。聚合反应是制造塑料、橡胶、纤维等的基础。" },

  // 常见物质（15题）
  { q: "下列关于水的说法，正确的是？", options: ["水的化学式为H2O", "水是由氢气和氧气组成的", "水是单质", "水不能做溶剂"], answer: 0, explanation: "水的化学式为H2O，是由氢元素和氧元素组成的化合物（不是氢气和氧气）。水是最常见的溶剂，被称为万能溶剂。水是地球上最丰富的化合物。" },
  { q: "下列关于氧气的说法，正确的是？", options: ["氧气能支持燃烧但本身不可燃", "氧气可以燃烧", "氧气有毒", "氧气是无色无味液体"], answer: 0, explanation: "氧气（O2）是无色无味气体，能支持燃烧（助燃）但本身不可燃。氧气是呼吸作用必需的气体。氧气约占空气体积的21%。" },
  { q: "下列关于二氧化碳的说法，正确的是？", options: ["二氧化碳能灭火", "二氧化碳可以燃烧", "二氧化碳有毒", "二氧化碳是单质"], answer: 0, explanation: "CO2是无色无味气体，不自燃也不助燃，密度比空气大，可用于灭火（覆盖可燃物隔绝氧气）。CO2是温室气体，过多排放导致全球变暖。CO2能使澄清石灰水变浑浊。" },
  { q: "下列关于铁的说法，正确的是？", options: ["铁在潮湿空气中容易生锈", "铁在干燥空气中容易生锈", "铁不与酸反应", "铁是有色金属"], answer: 0, explanation: "铁在潮湿空气中容易生锈（生成氧化铁Fe2O3·nH2O）。防锈方法：保持干燥、涂油刷漆、镀金属等。铁是黑色金属（铁、铬、锰），不是有色金属。" },
  { q: "下列关于铝的说法，正确的是？", options: ["铝表面易形成致密氧化膜", "铝是重金属", "铝不能导电", "铝不与酸反应"], answer: 0, explanation: "铝是轻金属，表面易形成致密的氧化铝（Al2O3）薄膜，阻止进一步氧化，因此铝制品耐腐蚀。铝导电性好（仅次于银和铜），广泛用于电线电缆。" },
  { q: "下列关于铜的说法，正确的是？", options: ["铜是紫红色金属", "铜是银白色金属", "铜是黄金色金属", "铜是黑色金属"], answer: 0, explanation: "纯铜是紫红色（紫铜）金属，是少数有颜色的金属之一。铜导电性极好（仅次于银），导热性好，广泛用于电线、电缆、散热器等。铜绿（碱式碳酸铜）是铜锈的主要成分。" },
  { q: "下列关于氢气的说法，正确的是？", options: ["氢气是最轻的气体", "氢气比空气重", "氢气不支持燃烧", "氢气有颜色"], answer: 0, explanation: "氢气（H2）是无色无味气体，是密度最小的气体（最轻的气体），比空气轻得多。氢气可燃且燃烧产物只有水，是理想的清洁能源。" },
  { q: "下列关于氮气的说法，正确的是？", options: ["氮气约占空气体积的78%", "氮气能支持燃烧", "氮气有毒", "氮气是化合物"], answer: 0, explanation: "氮气（N2）是无色无味气体，约占空气体积的78%。氮气化学性质不活泼，常用作保护气（如食品包装、灯泡填充）。氮气是合成氨和氮肥的原料。" },
  { q: "下列关于盐酸的说法，正确的是？", options: ["盐酸是氯化氢的水溶液", "盐酸是氧化物", "盐酸是碱", "盐酸是盐"], answer: 0, explanation: "盐酸是氯化氢（HCl）溶于水形成的溶液，是强酸。浓盐酸有挥发性，在空气中形成白雾。盐酸用于制氯气、金属清洗、胃酸的主要成分等。" },
  { q: "下列关于硫酸的说法，正确的是？", options: ["浓硫酸有强烈的脱水性和吸水性", "硫酸是弱酸", "硫酸无毒", "硫酸不能与金属反应"], answer: 0, explanation: "硫酸（H2SO4）是强酸。浓硫酸有强烈的脱水性（使有机物碳化）和吸水性（可作干燥剂），还有强氧化性。稀硫酸与活泼金属反应生成氢气。" },
  { q: "下列关于氢氧化钠的说法，正确的是？", options: ["氢氧化钠是强碱，俗称烧碱", "氢氧化钠是酸", "氢氧化钠是盐", "氢氧化钠是氧化物"], answer: 0, explanation: "氢氧化钠（NaOH）是强碱，俗称烧碱、火碱、苛性钠。有强烈的腐蚀性，易溶于水放热。广泛用于造纸、纺织、制皂等工业。使用时需注意安全。" },
  { q: "下列关于碳酸钙的说法，正确的是？", options: ["碳酸钙是大理石的主要成分", "碳酸钙是单质", "碳酸钙易溶于水", "碳酸钙是有机物"], answer: 0, explanation: "碳酸钙（CaCO3）是大理石、石灰石的主要成分。不溶于水，高温分解：CaCO3→CaO+CO2。碳酸钙是补钙剂的成分之一，也用于建筑材料。" },
  { q: "下列关于食盐的说法，正确的是？", options: ["食盐的主要成分是NaCl", "食盐是碱", "食盐是酸", "食盐是有机物"], answer: 0, explanation: "食盐的主要成分是氯化钠（NaCl），是离子化合物。食盐是人体必需的物质，用于调味和食品防腐。工业上用电解食盐水制取NaOH、Cl2和H2。" },
  { q: "下列关于一氧化碳的说法，正确的是？", options: ["一氧化碳有毒，能与血红蛋白结合", "一氧化碳无毒", "一氧化碳有刺激性气味", "一氧化碳是化合物但不含碳"], answer: 0, explanation: "一氧化碳（CO）是无色无味有毒气体，与血红蛋白结合能力远强于氧气，导致组织缺氧中毒。CO可燃，是良好的还原剂，用于冶炼金属。" },
  { q: "下列关于氨气的说法，正确的是？", options: ["氨气有刺激性气味", "氨气无毒", "氨气是氧化物", "氨气不能溶于水"], answer: 0, explanation: "氨气（NH3）是无色有刺激性气味的气体，极易溶于水（1:700），水溶液呈碱性（氨水）。氨气是制取氮肥（尿素、硝酸铵等）的重要原料。" },

  // 化学与生活（10题）
  { q: "下列关于食品添加剂的说法，正确的是？", options: ["合理使用食品添加剂是安全的", "所有食品添加剂都有害", "食品添加剂都是化学合成物", "天然食品不含添加剂"], answer: 0, explanation: "合理使用食品添加剂是安全的，可以改善食品品质和防腐需要。食品添加剂包括天然和合成两类，如防腐剂（苯甲酸钠）、色素（胡萝卜素）、增味剂（味精）等。" },
  { q: "下列关于洗涤剂的说法，正确的是？", options: ["洗涤剂的去污原理是乳化作用", "洗涤剂是酸", "洗涤剂只能洗油污", "洗涤剂有毒"], answer: 0, explanation: "洗涤剂含有表面活性剂，其去污原理是乳化作用——将油污分散成细小液滴使其脱离衣物。肥皂的去污原理也类似，但肥皂在硬水中效果差。" },
  { q: "下列关于干电池的说法，正确的是？", options: ["干电池是一次电池", "干电池可以反复充电", "干电池是蓄电池", "干电池不含金属"], answer: 0, explanation: "普通干电池（锌锰电池）是一次电池，不能充电反复使用。蓄电池（如铅酸蓄电池、锂电池）可以反复充放电。废弃电池应回收，防止重金属污染。" },
  { q: "下列关于塑料的说法，正确的是？", options: ["塑料不易降解会造成白色污染", "塑料可以自然降解", "塑料是天然材料", "塑料对环境无害"], answer: 0, explanation: "塑料是合成高分子材料，不易在自然条件下降解，会造成白色污染。减少白色污染的方法：减少使用一次性塑料制品、使用可降解塑料、回收再利用。" },
  { q: "人体缺铁会引起？", options: ["贫血", "佝偻病", "甲状腺肿大", "夜盲症"], answer: 0, explanation: "铁是合成血红蛋白的必需元素，缺铁会引起缺铁性贫血。含铁丰富的食物有动物肝脏、瘦肉、菠菜等。缺钙引起佝偻病，缺碘引起甲状腺肿大，缺维生素A引起夜盲症。" },
  { q: "人体缺钙会引起？", options: ["骨质疏松", "贫血", "甲状腺肿大", "坏血病"], answer: 0, explanation: "钙是构成骨骼和牙齿的主要成分，缺钙会引起骨质疏松、佝偻病等。含钙丰富的食物有牛奶、豆制品、虾皮等。维生素D促进钙的吸收。" },
  { q: "人体缺碘会引起？", options: ["甲状腺肿大", "贫血", "骨质疏松", "夜盲症"], answer: 0, explanation: "碘是甲状腺激素的组成成分，缺碘会引起甲状腺肿大（大脖子病），影响智力发育。含碘丰富的食物有海带、紫菜等。碘盐是预防碘缺乏的有效措施。" },
  { q: "下列关于味精的说法，正确的是？", options: ["味精的主要成分是谷氨酸钠", "味精是化学毒物", "味精不能食用", "味精是防腐剂"], answer: 0, explanation: "味精的主要成分是谷氨酸钠，是一种安全的增味剂。味精在高温下会失去鲜味，因此应在菜肴出锅前加入。适量使用味精是安全的。" },
  { q: "下列关于维生素C的说法，正确的是？", options: ["维生素C缺乏会引起坏血病", "维生素C缺乏会引起夜盲症", "维生素C是脂溶性维生素", "维生素C不能从食物获取"], answer: 0, explanation: "维生素C（抗坏血酸）是水溶性维生素，缺乏会引起坏血病（牙龈出血等）。维生素C主要存在于新鲜蔬果中（柑橘、番茄等），高温易被破坏。" },
  { q: "下列关于维生素D的说法，正确的是？", options: ["维生素D促进钙的吸收", "维生素D是水溶性的", "维生素D缺乏引起贫血", "维生素D不能自身合成"], answer: 0, explanation: "维生素D是脂溶性维生素，能促进钙和磷的吸收，缺乏会引起佝偻病和软骨病。人体皮肤在阳光照射下可合成维生素D，也可从鱼肝油、蛋黄等食物中获取。" },

  // ==================== 生物（100题）====================
  // 细胞（15题）
  { q: "细胞学说是由谁提出的？", options: ["施莱登和施旺", "达尔文", "孟德尔", "摩尔根"], answer: 0, explanation: "细胞学说由德国科学家施莱登和施旺于1838-1839年提出，主要内容：一切生物都是由细胞构成的，细胞是生物体结构和功能的基本单位。恩格斯将细胞学说列为19世纪三大发现之一。" },
  { q: "细胞的基本结构不包括？", options: ["细胞骨架", "细胞膜", "细胞质", "细胞核"], answer: 0, explanation: "细胞的基本结构包括细胞膜、细胞质和细胞核（原核细胞无细胞核，只有拟核）。细胞骨架虽然存在于细胞中，但不属于最基本结构的传统分类。" },
  { q: "动物细胞和植物细胞都有的结构是？", options: ["细胞膜、细胞质、细胞核", "细胞壁、叶绿体、液泡", "细胞壁、细胞膜", "叶绿体、细胞核"], answer: 0, explanation: "动物细胞和植物细胞共有细胞膜、细胞质和细胞核。植物细胞特有的结构是细胞壁、叶绿体和液泡。动物细胞没有这些结构（中心体动物细胞有，低等植物细胞也有）。" },
  { q: "植物细胞特有的结构是？", options: ["细胞壁、叶绿体、液泡", "细胞膜、细胞核", "线粒体、核糖体", "中心体、溶酶体"], answer: 0, explanation: "植物细胞特有的结构包括细胞壁（支持和保护）、叶绿体（光合作用）和液泡（储存物质、维持渗透压）。动物细胞没有这些结构。" },
  { q: "细胞膜的功能是？", options: ["控制物质进出细胞和保护细胞", "合成蛋白质", "进行光合作用", "储存遗传信息"], answer: 0, explanation: "细胞膜的主要功能是控制物质进出细胞（选择透过性）和保护细胞内部结构。细胞膜还具有细胞识别、信息传递等功能。细胞膜的基本骨架是磷脂双分子层。" },
  { q: "线粒体的功能是？", options: ["细胞的动力工厂，进行有氧呼吸", "合成蛋白质", "进行光合作用", "储存遗传信息"], answer: 0, explanation: "线粒体是细胞的动力工厂，是进行有氧呼吸的主要场所，为细胞生命活动提供能量（ATP）。线粒体含有自己的DNA，能半自主复制。" },
  { q: "叶绿体的功能是？", options: ["进行光合作用", "进行有氧呼吸", "合成蛋白质", "储存水分"], answer: 0, explanation: "叶绿体是植物细胞进行光合作用的场所，含有叶绿素和类胡萝卜素等色素，能吸收光能将CO2和水合成有机物并释放氧气。叶绿体也含有自己的DNA。" },
  { q: "核糖体的功能是？", options: ["合成蛋白质", "进行光合作用", "进行呼吸作用", "储存遗传信息"], answer: 0, explanation: "核糖体是细胞内合成蛋白质的场所，由rRNA和蛋白质组成。核糖体可游离在细胞质中，也可附着在内质网上。没有核糖体，细胞无法合成蛋白质。" },
  { q: "细胞核的功能是？", options: ["遗传信息库和细胞代谢控制中心", "合成蛋白质", "进行光合作用", "提供能量"], answer: 0, explanation: "细胞核是遗传信息库（含DNA），是细胞代谢和遗传的控制中心。细胞核由核膜、核仁和染色质组成。细胞核控制着细胞的生长、分裂和遗传特性。" },
  { q: "有丝分裂的意义是？", options: ["保持遗传物质的稳定", "产生遗传多样性", "减少染色体数目", "产生生殖细胞"], answer: 0, explanation: "有丝分裂的意义是产生的子细胞与母细胞具有相同的遗传物质，保证了遗传的稳定性。有丝分裂是体细胞增殖的方式，包括前期、中期、后期和末期。" },
  { q: "减数分裂的意义是？", options: ["产生遗传多样性", "保持遗传物质完全相同", "增加染色体数目", "产生体细胞"], answer: 0, explanation: "减数分裂产生染色体数目减半的生殖细胞（配子），受精后恢复二倍体数目。减数分裂中同源染色体分离和非同源染色体自由组合，产生遗传多样性。" },
  { q: "减数分裂的结果是？", options: ["产生4个染色体数目减半的子细胞", "产生2个与母细胞相同的子细胞", "产生4个与母细胞相同的子细胞", "产生2个染色体数目加倍的子细胞"], answer: 0, explanation: "减数分裂包括减数第一次分裂和减数第二次分裂，一个母细胞经过减数分裂产生4个染色体数目减半的子细胞（配子）。这是有性生殖的基础。" },
  { q: "DNA主要存在于？", options: ["细胞核中", "细胞膜中", "细胞质基质中", "核糖体中"], answer: 0, explanation: "DNA主要存在于细胞核中（染色质的主要成分），少量存在于线粒体和叶绿体中。原核细胞DNA在拟核区域。RNA主要存在于细胞质中。" },
  { q: "原核细胞和真核细胞的主要区别是？", options: ["有无成形的细胞核", "有无细胞膜", "有无细胞质", "有无DNA"], answer: 0, explanation: "原核细胞没有成形的细胞核（只有拟核，DNA裸露），也没有膜包细胞器。真核细胞有成形的细胞核（核膜包被）和多种膜包细胞器。细菌是原核生物，动植物是真核生物。" },
  { q: "细胞分裂的意义不包括？", options: ["增加细胞的种类", "生物体生长", "产生新个体", "替换衰老死亡细胞"], answer: 0, explanation: "细胞分裂的意义包括：生物体生长（细胞数量增多）、产生新个体（生殖）、替换衰老死亡细胞。细胞分裂不能增加细胞种类，细胞分化才能形成不同种类的细胞。" },

  // 遗传（20题）
  { q: "DNA的双螺旋结构是由谁发现的？", options: ["沃森和克里克", "孟德尔", "达尔文", "摩尔根"], answer: 0, explanation: "1953年，沃森和克里克发现DNA双螺旋结构，这是20世纪生物学最伟大的发现之一。他们因此获得1962年诺贝尔生理学或医学奖。富兰克林的X射线衍射数据对此发现至关重要。" },
  { q: "DNA的基本组成单位是？", options: ["脱氧核苷酸", "氨基酸", "核糖核苷酸", "葡萄糖"], answer: 0, explanation: "DNA的基本组成单位是脱氧核苷酸，由磷酸、脱氧核糖和含氮碱基（A、T、G、C）组成。RNA的基本组成单位是核糖核苷酸，碱基为A、U、G、C。" },
  { q: "DNA中含有的碱基是？", options: ["腺嘌呤、胸腺嘧啶、鸟嘌呤、胞嘧啶", "腺嘌呤、尿嘧啶、鸟嘌呤、胞嘧啶", "腺嘌呤、胸腺嘧啶、尿嘧啶、胞嘧啶", "腺嘌呤、尿嘧啶、鸟嘌呤、胸腺嘧啶"], answer: 0, explanation: "DNA含四种碱基：腺嘌呤(A)、胸腺嘧啶(T)、鸟嘌呤(G)、胞嘧啶(C)。RNA中用尿嘧啶(U)代替胸腺嘧啶(T)。碱基配对规律：A-T（DNA中）或A-U（RNA中），G-C。" },
  { q: "DNA的碱基配对规律是？", options: ["A-T, G-C", "A-U, G-C", "A-G, T-C", "A-C, T-G"], answer: 0, explanation: "DNA双链间的碱基配对规律是A-T（腺嘌呤与胸腺嘧啶配对，2个氢键）和G-C（鸟嘌呤与胞嘧啶配对，3个氢键）。在RNA中A与U配对。" },
  { q: "RNA与DNA的主要区别是？", options: ["RNA是单链，DNA是双链", "RNA是双链，DNA是单链", "RNA没有碱基", "DNA没有碱基"], answer: 0, explanation: "RNA通常是单链结构，DNA是双链双螺旋结构。此外RNA含核糖（DNA含脱氧核糖），RNA的碱基用U代替DNA中的T。RNA主要有mRNA、tRNA和rRNA三种。" },
  { q: "基因是？", options: ["有遗传效应的DNA片段", "整个DNA分子", "蛋白质片段", "RNA分子"], answer: 0, explanation: "基因是具有遗传效应的DNA片段（部分病毒为RNA），是控制生物性状的遗传单位。每个基因包含特定的碱基序列，编码特定的蛋白质或RNA。" },
  { q: "孟德尔第一定律又称？", options: ["分离定律", "自由组合定律", "连锁交换定律", "独立分配定律"], answer: 0, explanation: "孟德尔第一定律是分离定律：在形成配子时，成对的遗传因子彼此分离，分别进入不同的配子中。这一定律揭示了等位基因的遗传规律。" },
  { q: "孟德尔第二定律又称？", options: ["自由组合定律", "分离定律", "连锁交换定律", "显性定律"], answer: 0, explanation: "孟德尔第二定律是自由组合定律：在形成配子时，位于非同源染色体上的非等位基因自由组合。这一定律揭示了不同基因之间的遗传规律。" },
  { q: "孟德尔遗传实验选用的实验材料是？", options: ["豌豆", "果蝇", "玉米", "小鼠"], answer: 0, explanation: "孟德尔选用豌豆作为实验材料，因为豌豆是严格自花传粉植物，具有明显的相对性状，易于人工授粉杂交。孟德尔通过豌豆杂交实验发现了遗传规律。" },
  { q: "下列属于相对性状的是？", options: ["豌豆的高茎和矮茎", "人的身高和体重", "猫的颜色和大小", "花的颜色和形状"], answer: 0, explanation: "相对性状是同种生物同一性状的不同表现类型。豌豆的高茎和矮茎是相对性状（同一性状的不同表现）。身高和体重是不同性状。颜色和大小也是不同性状。" },
  { q: "显性基因和隐性基因的表示方法通常是？", options: ["大写字母和小写字母", "数字和字母", "希腊字母", "中文和英文"], answer: 0, explanation: "显性基因通常用大写字母表示（如A），隐性基因用小写字母表示（如a）。AA为显性纯合子，aa为隐性纯合子，Aa为杂合子（表现显性性状）。" },
  { q: "杂合子Aa自交，后代中显性性状与隐性性状的比例为？", options: ["3:1", "1:1", "2:1", "3:2"], answer: 0, explanation: "杂合子Aa自交（Aa×Aa），后代基因型为AA:Aa:aa=1:2:1，表现型为显性:隐性=3:1。这是孟德尔分离定律的典型比例（完全显性条件下）。" },
  { q: "人类基因组有多少对染色体？", options: ["23对", "46对", "22对", "24对"], answer: 0, explanation: "人类体细胞有23对（46条）染色体，其中22对为常染色体，1对为性染色体（XX为女性，XY为男性）。生殖细胞（精子和卵子）有23条染色体。" },
  { q: "人类基因组计划完成于哪一年？", options: ["2003年", "1990年", "2000年", "2010年"], answer: 0, explanation: "人类基因组计划于1990年启动，2003年完成（草图于2000年完成），测定了人类基因组的全部DNA序列。该计划由美、英、法、德、日、中六国科学家共同完成。" },
  { q: "下列关于性染色体的说法，正确的是？", options: ["XY为男性，XX为女性", "XX为男性，XY为女性", "Y染色体比X染色体大", "性染色体只有一条"], answer: 0, explanation: "人类性染色体组合：XY为男性，XX为女性。Y染色体比X染色体小得多。性染色体决定性别，Y染色体上的SRY基因是决定男性的关键基因。" },
  { q: "色盲是一种什么遗传病？", options: ["X染色体隐性遗传", "常染色体显性遗传", "Y染色体遗传", "常染色体隐性遗传"], answer: 0, explanation: "红绿色盲是X染色体隐性遗传病。男性（XY）只要X染色体上带有色盲基因就会患病，女性（XX）需要两个X染色体都带有色盲基因才患病。因此男性色盲发病率远高于女性。" },
  { q: "下列关于遗传和变异的说法，正确的是？", options: ["遗传是相对的，变异是绝对的", "遗传是绝对的，变异是相对的", "遗传和变异都是相对的", "遗传和变异都是绝对的"], answer: 0, explanation: "遗传是相对的（子代与亲代基本相似），变异是绝对的（没有完全相同的个体）。遗传保持物种的稳定性，变异为生物进化提供原材料。遗传和变异是生物的基本特征。" },
  { q: "中心法则描述的是？", options: ["遗传信息的传递和表达过程", "蛋白质的合成过程", "DNA的复制过程", "细胞的分裂过程"], answer: 0, explanation: "中心法则描述遗传信息的传递方向：DNA→RNA→蛋白质（转录和翻译），以及DNA→DNA（复制）。后来发现RNA→DNA（逆转录）和RNA→RNA（RNA复制）也属于中心法则。" },
  { q: "转录是指？", options: ["以DNA为模板合成RNA的过程", "以RNA为模板合成蛋白质的过程", "DNA的复制过程", "RNA的复制过程"], answer: 0, explanation: "转录是以DNA一条链为模板合成RNA的过程，在细胞核中进行。转录时DNA的碱基A、T、G、C分别对应RNA的U、A、C、G。转录是基因表达的第一步。" },
  { q: "翻译是指？", options: ["以mRNA为模板合成蛋白质的过程", "以DNA为模板合成RNA的过程", "DNA的复制过程", "RNA的复制过程"], answer: 0, explanation: "翻译是以mRNA为模板，在核糖体上合成蛋白质的过程。mRNA上每三个相邻碱基（密码子）决定一个氨基酸。tRNA负责将氨基酸运送到核糖体。翻译在细胞质中进行。" },

  // 进化（10题）
  { q: "提出自然选择学说的科学家是？", options: ["达尔文", "拉马克", "孟德尔", "摩尔根"], answer: 0, explanation: "达尔文于1859年在《物种起源》中提出自然选择学说，核心内容是过度繁殖、生存斗争、遗传变异和适者生存。自然选择是生物进化的主要动力。" },
  { q: "达尔文进化论的核心是？", options: ["自然选择", "用进废退", "获得性遗传", "突变选择"], answer: 0, explanation: "达尔文进化论的核心是自然选择。在过度繁殖和生存斗争的基础上，具有有利变异的个体容易生存并繁衍后代，不利变异的个体被淘汰，即适者生存。" },
  { q: "拉马克的进化观点是？", options: ["用进废退和获得性遗传", "自然选择", "适者生存", "基因突变"], answer: 0, explanation: "拉马克提出用进废退和获得性遗传的进化观点，认为器官越用越发达、不用则退化，后天获得的性状可以遗传给后代。这一观点后来被证明是不正确的。" },
  { q: "现代生物进化理论的核心是？", options: ["以自然选择为基础的综合进化理论", "用进废退", "获得性遗传", "灾变论"], answer: 0, explanation: "现代生物进化理论以达尔文自然选择学说为基础，结合遗传学、分子生物学等，形成综合进化理论。认为种群是进化的基本单位，突变和基因重组提供原材料，自然选择决定进化方向。" },
  { q: "生物进化的基本单位是？", options: ["种群", "个体", "群落", "生态系统"], answer: 0, explanation: "种群是生物进化的基本单位。种群是生活在一定区域的同种生物的全部个体。进化是种群基因频率的变化过程，个体不能进化，只有种群才能进化。" },
  { q: "生物进化的原材料来源于？", options: ["突变和基因重组", "自然选择", "环境变化", "人工选择"], answer: 0, explanation: "突变（基因突变、染色体变异）和基因重组为生物进化提供原材料。突变产生新的等位基因，基因重组产生新的基因组合。自然选择决定哪些变异被保留。" },
  { q: "自然选择直接作用于？", options: ["个体的表型", "个体的基因型", "种群基因库", "环境因子"], answer: 0, explanation: "自然选择直接作用于个体的表型（表现型），因为自然选择是通过环境对个体生存和繁殖的影响来实现的。表型由基因型和环境共同决定，被选择的表型进而影响基因频率。" },
  { q: "物种形成的标志是？", options: ["生殖隔离", "地理隔离", "形态差异", "行为差异"], answer: 0, explanation: "物种形成的标志是生殖隔离——不同种群间不能交配或交配后不能产生可育后代。地理隔离是物种形成的常见途径，但不是最终标志。生殖隔离可以是合子前隔离或合子后隔离。" },
  { q: "适应是自然选择的什么结果？", options: ["长期定向选择的结果", "随机变化的结果", "环境直接诱导的结果", "生物主观选择的结果"], answer: 0, explanation: "适应是自然选择长期定向选择的结果。具有有利变异的个体在生存斗争中胜出并繁衍后代，有利性状在种群中逐渐积累，形成对环境的适应。适应是相对的。" },
  { q: "下列关于生物多样性的说法，正确的是？", options: ["包括基因多样性、物种多样性和生态系统多样性", "只包括物种多样性", "只包括基因多样性", "与进化无关"], answer: 0, explanation: "生物多样性包括基因多样性（遗传多样性）、物种多样性和生态系统多样性三个层次。生物多样性是生物进化的结果，保护生物多样性对维持生态平衡和人类生存至关重要。" },

  // 人体系统（20题）
  { q: "人体消化系统的主要功能是？", options: ["消化食物和吸收营养", "运输氧气", "排出废物", "调节体温"], answer: 0, explanation: "消化系统的主要功能是消化食物（将大分子分解为小分子）和吸收营养。消化道包括口腔、食道、胃、小肠、大肠、肛门。小肠是消化和吸收的主要场所。" },
  { q: "人体吸收营养的主要器官是？", options: ["小肠", "胃", "大肠", "口腔"], answer: 0, explanation: "小肠是人体吸收营养的主要器官。小肠内有大量绒毛和微绒毛增大吸收面积，小肠长约5-6米。大部分营养在小肠吸收，水和无机盐主要在大肠吸收。" },
  { q: "人体最大的消化腺是？", options: ["肝脏", "唾液腺", "胃腺", "肠腺"], answer: 0, explanation: "肝脏是人体最大的消化腺（也是最大的内脏器官），分泌胆汁储存在胆囊中。胆汁不含消化酶，但能乳化脂肪（将大脂肪滴分散成小脂肪滴），有利于脂肪消化。" },
  { q: "唾液中含有的消化酶是？", options: ["唾液淀粉酶", "胃蛋白酶", "脂肪酶", "胰蛋白酶"], answer: 0, explanation: "唾液中含有唾液淀粉酶，能将淀粉分解为麦芽糖。这就是细嚼米饭觉得甜的原因。胃液含胃蛋白酶，胰液含胰蛋白酶和脂肪酶等多种酶。" },
  { q: "人体呼吸系统的主要器官是？", options: ["肺", "心脏", "肝脏", "肾脏"], answer: 0, explanation: "肺是呼吸系统的主要器官，是气体交换的场所。呼吸道包括鼻腔、咽、喉、气管和支气管，是气体进出肺的通道。肺泡是肺内气体交换的基本单位。" },
  { q: "人体内气体交换的原理是？", options: ["气体的扩散作用", "主动运输", "渗透作用", "呼吸运动"], answer: 0, explanation: "气体交换通过气体的扩散作用实现——气体从浓度高处向浓度低处扩散。在肺泡处O2进入血液、CO2进入肺泡；在组织处O2进入组织细胞、CO2进入血液。" },
  { q: "人体血液循环的途径包括？", options: ["体循环和肺循环", "动脉循环和静脉循环", "大循环和小循环", "心脏循环和血管循环"], answer: 0, explanation: "人体血液循环包括体循环（大循环：左心室→主动脉→全身各组织→上下腔静脉→右心房）和肺循环（小循环：右心室→肺动脉→肺泡→肺静脉→左心房）。" },
  { q: "正常成年人的心率范围是？", options: ["60~100次/分", "40~60次/分", "100~150次/分", "20~40次/分"], answer: 0, explanation: "正常成年人安静时心率为60~100次/分（平均约75次/分）。运动员心率可低于60次/分（因为心脏泵血效率高）。心率过快或过慢都可能是心脏疾病的信号。" },
  { q: "人体正常的血压范围是？", options: ["收缩压90~139mmHg，舒张压60~89mmHg", "收缩压80~120mmHg，舒张压50~70mmHg", "收缩压100~160mmHg，舒张压70~100mmHg", "收缩压70~100mmHg，舒张压40~60mmHg"], answer: 0, explanation: "正常血压：收缩压90~139mmHg，舒张压60~89mmHg。高血压标准：收缩压≥140mmHg和/或舒张压≥90mmHg。低血压：收缩压<90mmHg和/或舒张压<60mmHg。" },
  { q: "血液中运输氧气的细胞是？", options: ["红细胞", "白细胞", "血小板", "血浆"], answer: 0, explanation: "红细胞负责运输氧气（通过血红蛋白与O2结合）。白细胞负责免疫防御。血小板参与血液凝固。血浆运输营养物质、废物和激素等。" },
  { q: "血红蛋白的特点是？", options: ["在氧浓度高处与氧结合，在氧浓度低处与氧分离", "在氧浓度低处与氧结合", "不能与氧结合", "只与二氧化碳结合"], answer: 0, explanation: "血红蛋白在氧浓度高处（肺泡）与氧结合形成氧合血红蛋白，在氧浓度低处（组织）与氧分离释放氧气。这种特性使红细胞能高效运输氧气。CO与血红蛋白结合能力远强于O2。" },
  { q: "泌尿系统的主要器官是？", options: ["肾脏", "肝脏", "心脏", "肺"], answer: 0, explanation: "肾脏是泌尿系统的主要器官，是形成尿液的场所。泌尿系统包括肾脏、输尿管、膀胱和尿道。肾脏的基本功能单位是肾单位（包括肾小球和肾小管）。" },
  { q: "尿液的形成过程包括？", options: ["肾小球滤过和肾小管重吸收", "肾小球分泌和肾小管排泄", "肾小囊滤过和集合管重吸收", "肾小管滤过和肾小球重吸收"], answer: 0, explanation: "尿液形成包括两个步骤：肾小球滤过（形成原尿，约180L/天）；肾小管重吸收（原尿中大部分水、全部葡萄糖、部分无机盐被重吸收，形成终尿约1.5L/天）。" },
  { q: "神经系统结构和功能的基本单位是？", options: ["神经元", "神经纤维", "神经末梢", "神经胶质细胞"], answer: 0, explanation: "神经元（神经细胞）是神经系统结构和功能的基本单位，由胞体、树突和轴突组成。神经元通过突触传递神经冲动。神经胶质细胞起支持、保护和营养作用。" },
  { q: "反射的神经基础是？", options: ["反射弧", "神经中枢", "感受器", "效应器"], answer: 0, explanation: "反射是通过反射弧完成的。反射弧包括感受器→传入神经→神经中枢→传出神经→效应器五个部分。反射分为条件反射（后天获得）和非条件反射（天生具有）。" },
  { q: "下列属于条件反射的是？", options: ["望梅止渴", "缩手反射", "眨眼反射", "膝跳反射"], answer: 0, explanation: "望梅止渴是条件反射（后天获得，需要大脑参与）。缩手反射、眨眼反射、膝跳反射都是非条件反射（天生具有，不需要大脑参与，由脊髓完成）。" },
  { q: "人体最大的内分泌腺是？", options: ["甲状腺", "肾上腺", "胰岛", "垂体"], answer: 0, explanation: "甲状腺是人体最大的内分泌腺，分泌甲状腺激素（促进新陈代谢、生长发育和神经系统的发育）。碘是合成甲状腺激素的必需元素，缺碘会引起甲状腺肿大。" },
  { q: "胰岛素由哪个器官分泌？", options: ["胰岛", "甲状腺", "肾上腺", "垂体"], answer: 0, explanation: "胰岛素由胰岛（胰腺中的内分泌部分）的β细胞分泌，能降低血糖浓度。胰岛素不足会导致糖尿病。糖尿病患者需要注射胰岛素治疗（口服会被消化酶分解）。" },
  { q: "生长激素由哪个器官分泌？", options: ["垂体", "甲状腺", "肾上腺", "胰岛"], answer: 0, explanation: "生长激素由垂体（脑垂体）分泌，促进生长发育。幼年时生长激素分泌不足引起侏儒症，分泌过多引起巨人症，成年后分泌过多引起肢端肥大症。垂体是内分泌之王。" },
  { q: "免疫系统的主要功能是？", options: ["防御、监控和清除", "消化吸收", "运输氧气", "调节体温"], answer: 0, explanation: "免疫系统有三大功能：防御（抵抗病原体入侵）；监控（识别和清除异常细胞）；清除（清除衰老、损伤和死亡的细胞）。免疫功能失调会引起过敏或自身免疫疾病。" },

  // 植物（10题）
  { q: "光合作用的场所是？", options: ["叶绿体", "线粒体", "细胞核", "细胞膜"], answer: 0, explanation: "光合作用在叶绿体中进行。光合作用是绿色植物利用光能将CO2和水合成有机物（葡萄糖）并释放氧气的过程。叶绿体中的叶绿素吸收光能。" },
  { q: "光合作用的反应条件是？", options: ["光照", "黑暗", "高温", "低温"], answer: 0, explanation: "光合作用需要光照（光反应阶段需要光）。光合作用分为光反应（在类囊体膜上进行）和暗反应（在叶绿体基质中进行）两个阶段。光反应为暗反应提供ATP和NADPH。" },
  { q: "光合作用的原料是？", options: ["二氧化碳和水", "氧气和水", "葡萄糖和氧气", "葡萄糖和水"], answer: 0, explanation: "光合作用的原料是CO2和水，产物是有机物（葡萄糖）和氧气，条件是光照，场所是叶绿体。光合作用表达式：CO2+H2O→(光照/叶绿体)→有机物+O2。" },
  { q: "植物呼吸作用的场所是？", options: ["线粒体", "叶绿体", "细胞核", "细胞膜"], answer: 0, explanation: "植物呼吸作用主要在线粒体中进行。呼吸作用是细胞利用氧气将有机物分解为CO2和水，释放能量的过程。释放的能量用于生命活动，部分以热能形式散失。" },
  { q: "植物呼吸作用与光合作用的关系是？", options: ["相互对立又相互依存", "互不相关", "只有光合作用重要", "只有呼吸作用重要"], answer: 0, explanation: "光合作用和呼吸作用相互对立又相互依存。光合作用合成有机物、储存能量、吸收CO2释放O2；呼吸作用分解有机物、释放能量、吸收O2释放CO2。光合为呼吸提供物质和能量，呼吸为光合提供CO2。" },
  { q: "植物的蒸腾作用主要通过哪个结构进行？", options: ["气孔", "根毛", "茎的导管", "花瓣"], answer: 0, explanation: "蒸腾作用主要通过叶片上的气孔进行（约90%以上）。气孔由保卫细胞控制开闭。蒸腾作用促进水分和无机盐的运输、降低叶片温度，是植物根系吸水的主要动力。" },
  { q: "植物根系吸水的主要部位是？", options: ["根毛区", "根冠", "分生区", "伸长区"], answer: 0, explanation: "根毛区（成熟区）是根系吸水的主要部位，根毛大大增加了吸收面积。水分通过渗透作用进入根毛细胞，经根的导管向上运输到茎和叶。" },
  { q: "植物进行光合作用和蒸腾作用的主要器官是？", options: ["叶", "茎", "根", "花"], answer: 0, explanation: "叶是植物进行光合作用和蒸腾作用的主要器官。叶片的叶绿体进行光合作用，叶片上的气孔是蒸腾作用的主要通道。叶的形态结构适应了这些功能。" },
  { q: "植物的导管运输的是？", options: ["水分和无机盐", "有机物", "氧气", "二氧化碳"], answer: 0, explanation: "导管位于木质部，由下向上运输水分和无机盐。筛管位于韧皮部，由上向下运输有机物（叶片光合作用产物）。导管是死细胞，筛管是活细胞。" },
  { q: "下列关于植物激素的说法，正确的是？", options: ["生长素能促进植物生长", "生长素抑制植物生长", "乙烯促进生长", "赤霉素抑制生长"], answer: 0, explanation: "生长素（吲哚乙酸）能促进植物生长（低浓度促进，高浓度抑制）。乙烯促进果实成熟。赤霉素促进茎的伸长。脱落酸抑制生长、促进衰老脱落。植物激素调节植物生长发育。" },

  // 微生物（10题）
  { q: "细菌属于？", options: ["原核生物", "真核生物", "非细胞生物", "植物"], answer: 0, explanation: "细菌是原核生物，没有成形的细胞核（只有拟核），也没有膜包细胞器。细菌有细胞壁、细胞膜和细胞质。细菌通过二分裂繁殖，分布广泛。" },
  { q: "病毒的基本结构是？", options: ["蛋白质外壳和核酸", "细胞壁和细胞膜", "细胞核和细胞质", "只有核酸"], answer: 0, explanation: "病毒是非细胞生物，基本结构是蛋白质外壳（衣壳）和内部的核酸（DNA或RNA）。病毒没有细胞结构，必须寄生在活细胞中才能繁殖，离开活细胞后无生命活动。" },
  { q: "病毒必须寄生在什么中才能繁殖？", options: ["活细胞", "死亡的细胞", "有机物", "无机环境"], answer: 0, explanation: "病毒是专性寄生物，必须寄生在活细胞中才能繁殖。病毒利用宿主细胞的物质和能量进行复制。病毒可感染细菌（噬菌体）、植物、动物和人类。" },
  { q: "下列关于真菌的说法，正确的是？", options: ["真菌是真核生物", "真菌是原核生物", "真菌没有细胞核", "真菌是非细胞生物"], answer: 0, explanation: "真菌是真核生物，有成形的细胞核和细胞器。常见的真菌有酵母菌、霉菌和蘑菇等。真菌多数营腐生生活，在生态系统中是分解者，对物质循环起重要作用。" },
  { q: "下列微生物中属于真核生物的是？", options: ["酵母菌", "大肠杆菌", "乳酸菌", "新冠病毒"], answer: 0, explanation: "酵母菌是真核生物（真菌）。大肠杆菌和乳酸菌是原核生物（细菌）。新冠病毒是非细胞生物（病毒）。酵母菌可用于酿酒和发面（发酵产生CO2和酒精）。" },
  { q: "细菌的繁殖方式是？", options: ["二分裂", "出芽生殖", "孢子生殖", "有性生殖"], answer: 0, explanation: "细菌主要通过二分裂繁殖（一个细胞分裂为两个），繁殖速度很快，条件适宜时20-30分钟分裂一次。酵母菌可出芽生殖，真菌可孢子生殖。" },
  { q: "下列关于噬菌体的说法，正确的是？", options: ["噬菌体是感染细菌的病毒", "噬菌体是细菌", "噬菌体是真菌", "噬菌体是原生动物"], answer: 0, explanation: "噬菌体是感染细菌的病毒，寄生在细菌细胞内繁殖，最终裂解细菌。噬菌体在分子生物学研究中被广泛应用（如作为基因克隆载体）。" },
  { q: "下列关于抗生素的说法，正确的是？", options: ["抗生素对病毒无效", "抗生素能杀死病毒", "抗生素对所有微生物有效", "抗生素是人工合成的"], answer: 0, explanation: "抗生素主要对细菌、真菌等有效，对病毒无效（因为病毒没有细胞结构）。抗生素由微生物产生（如青霉素由青霉菌产生），也有半合成和全合成的。滥用抗生素会导致耐药菌产生。" },
  { q: "下列关于疫苗的说法，正确的是？", options: ["疫苗是预防传染病的生物制品", "疫苗是抗生素", "疫苗能治疗所有疾病", "疫苗是化学药品"], answer: 0, explanation: "疫苗是用病原微生物或其成分制成的生物制品，注射或口服后刺激机体产生免疫反应，从而获得对该病原体的特异性免疫。疫苗是预防传染病的最有效手段。" },
  { q: "乳酸菌在食品制作中的应用是？", options: ["制作酸奶和泡菜", "酿酒", "制作面包", "制作酱油"], answer: 0, explanation: "乳酸菌发酵产生乳酸，用于制作酸奶、泡菜等。酵母菌用于酿酒和制作面包。醋酸菌用于制醋。霉菌用于制作酱油和豆腐乳。微生物发酵在食品工业中应用广泛。" },

  // 生物技术（10题）
  { q: "基因工程的核心是？", options: ["DNA重组技术", "细胞培养", "发酵技术", "组织培养"], answer: 0, explanation: "基因工程的核心是DNA重组技术，即将目的基因导入受体细胞使其表达。基本步骤：获取目的基因→构建表达载体→导入受体细胞→筛选和表达。基因工程已广泛应用于医药、农业等领域。" },
  { q: "克隆技术的基础是？", options: ["细胞核移植", "基因重组", "发酵工程", "酶工程"], answer: 0, explanation: "克隆技术的核心是细胞核移植——将体细胞核移入去核卵母细胞中，发育成新个体。1996年克隆羊多利是首例体细胞克隆哺乳动物。克隆属于无性繁殖。" },
  { q: "干细胞的特点是？", options: ["具有自我更新和分化潜能", "只能分化一种细胞", "不能分裂", "只在胚胎中存在"], answer: 0, explanation: "干细胞具有自我更新和多向分化潜能。胚胎干细胞可分化为所有类型的细胞（全能干细胞），成体干细胞分化潜能有限（如造血干细胞可分化为各种血细胞）。干细胞在再生医学中有广泛应用前景。" },
  { q: "CRISPR技术是一种？", options: ["基因编辑技术", "细胞培养技术", "发酵技术", "克隆技术"], answer: 0, explanation: "CRISPR-Cas9是一种基因编辑技术，能精确地切割和修改DNA序列，被誉为基因手术刀。该技术简便、高效、成本低，在基因治疗、农业育种等方面有广泛应用前景。2020年获得诺贝尔化学奖。" },
  { q: "下列关于转基因技术的说法，正确的是？", options: ["转基因技术可以改变生物的遗传性状", "转基因技术是自然过程", "转基因技术没有风险", "转基因技术只用于植物"], answer: 0, explanation: "转基因技术通过导入外源基因改变生物的遗传性状。转基因技术已应用于农作物（如抗虫棉、黄金大米）、医药（如胰岛素生产）等领域。转基因技术的安全性仍需长期评估。" },
  { q: "PCR技术的全称是？", options: ["聚合酶链式反应", "蛋白质链式反应", "多聚酶催化反应", "DNA复制反应"], answer: 0, explanation: "PCR（Polymerase Chain Reaction）即聚合酶链式反应，是一种体外大量扩增DNA的技术。PCR通过高温变性、低温退火、适温延伸三个步骤循环进行，可在短时间内将DNA扩增数百万倍。核酸检测就使用PCR技术。" },
  { q: "下列关于基因治疗的说法，正确的是？", options: ["基因治疗是向细胞导入正常基因以治疗疾病", "基因治疗是切除病变基因", "基因治疗是服用基因药物", "基因治疗已完全成熟"], answer: 0, explanation: "基因治疗是通过向患者细胞导入正常基因来替代或补偿缺陷基因的功能，从而治疗遗传性疾病。基因治疗仍处于发展阶段，面临技术、安全和伦理等挑战，但在某些遗传病治疗中已取得突破。" },
  { q: "下列关于单克隆抗体的说法，正确的是？", options: ["由杂交瘤细胞产生", "由细菌产生", "由植物产生", "由病毒产生"], answer: 0, explanation: "单克隆抗体由杂交瘤细胞产生。将产生抗体的B淋巴细胞与骨髓瘤细胞融合形成杂交瘤细胞，既能产生特异性抗体又能无限增殖。单克隆抗体广泛用于疾病诊断和治疗（如靶向治疗）。" },
  { q: "组织培养的理论基础是？", options: ["植物细胞的全能性", "细胞分裂", "基因重组", "自然选择"], answer: 0, explanation: "植物组织培养的理论基础是植物细胞的全能性——每个植物细胞都含有发育成完整植株的全部遗传信息。组织培养可快速繁殖优良品种、培育无病毒植株等，在农业和园艺中应用广泛。" },
  { q: "下列关于生物技术的说法，不正确的是？", options: ["生物技术只有优点没有风险", "生物技术有广泛的应用前景", "生物技术需要规范管理", "生物技术可能带来伦理问题"], answer: 0, explanation: "生物技术虽然前景广阔，但也存在风险和伦理问题（如基因编辑婴儿、转基因食品安全等），需要规范管理和伦理约束。生物技术不是只有优点没有风险的。" },

  // ==================== 前沿科技（100题）====================
  // 信息技术（20题）
  { q: "5G通信技术的最大特点是？", options: ["高速率、低时延、大连接", "覆盖范围广", "成本低", "仅用于手机"], answer: 0, explanation: "5G的三大特点：高速率（峰值速率可达10Gbps以上）、低时延（可低至1ms）和大连接（每平方公里百万级设备连接）。5G应用场景包括增强移动宽带、超可靠低时延通信和海量机器类通信。" },
  { q: "物联网的英文缩写是？", options: ["IoT", "IoE", "IPv6", "ITU"], answer: 0, explanation: "物联网（Internet of Things, IoT）是指通过传感器、射频识别等技术将物品与互联网连接，实现智能化识别、定位、跟踪和管理。物联网是智慧城市、智能家居等技术的基础。" },
  { q: "云计算的基本概念是？", options: ["通过网络提供计算资源和服务", "在本地计算机上运算", "天气预测技术", "数据存储技术"], answer: 0, explanation: "云计算是通过互联网提供计算资源（服务器、存储、数据库、软件等）和服务。云计算服务模式包括IaaS（基础设施即服务）、PaaS（平台即服务）和SaaS（软件即服务）。" },
  { q: "大数据的特征不包括？", options: ["体积小", "数据量大(Volume)", "处理速度快(Velocity)", "数据类型多(Variety)"], answer: 0, explanation: "大数据的特征通常概括为4V：Volume（数据量大）、Velocity（处理速度快）、Variety（数据类型多）和Value（价值密度低但总体价值高）。大数据不指体积小。" },
  { q: "区块链技术的核心特点是？", options: ["去中心化和不可篡改", "中心化管理", "数据可随意修改", "仅用于虚拟货币"], answer: 0, explanation: "区块链的核心特点是去中心化（无需中心机构）、不可篡改（数据一旦写入难以修改）和透明可追溯。区块链不仅用于虚拟货币（如比特币），还应用于供应链、版权保护等领域。" },
  { q: "6G通信技术的预期特点不包括？", options: ["完全取代5G且无需基站", "更高的传输速率", "更低的时延", "天地一体化通信"], answer: 0, explanation: "6G预期具有更高的传输速率（可达Tbps级）、更低的时延、更广的连接（天地一体化通信）。6G不会完全取代5G，而是在5G基础上发展，仍需要基础设施支撑。6G目前仍在研发阶段。" },
  { q: "云计算的服务模式不包括？", options: ["DaaS（数据即服务）", "IaaS（基础设施即服务）", "PaaS（平台即服务）", "SaaS（软件即服务）"], answer: 0, explanation: "云计算的三大基本服务模式是IaaS、PaaS和SaaS。DaaS（数据即服务）不是云计算的标准服务模式。IaaS提供计算基础设施，PaaS提供开发平台，SaaS提供应用软件。" },
  { q: "下列关于IPv6的说法，正确的是？", options: ["IPv6地址长度为128位", "IPv6地址长度为32位", "IPv6兼容所有IPv4设备", "IPv6已完全取代IPv4"], answer: 0, explanation: "IPv6地址长度为128位（IPv4为32位），地址数量约为3.4×10的38次方，几乎可以无限使用。IPv6解决了IPv4地址枯竭问题，提供更好的安全性和服务质量。IPv4和IPv6需要通过过渡技术兼容。" },
  { q: "边缘计算的特点是？", options: ["在数据源附近进行计算处理", "所有数据都传到云端处理", "不需要网络连接", "只能在服务器上运行"], answer: 0, explanation: "边缘计算在数据源（如传感器、设备）附近进行计算处理，减少数据传输延迟和带宽占用。边缘计算与云计算互补，适合实时性要求高的应用场景（如自动驾驶、工业控制）。" },
  { q: "数字孪生技术的概念是？", options: ["创建物理实体的虚拟数字模型", "克隆生物体", "数字化存储数据", "模拟数学计算"], answer: 0, explanation: "数字孪生是创建物理实体（如设备、建筑、城市）的虚拟数字模型，通过实时数据同步实现虚实交互。数字孪生广泛应用于智能制造、城市规划、医疗等领域，实现预测性维护和优化决策。" },
  { q: "Wi-Fi 6的协议标准是？", options: ["802.11ax", "802.11ac", "802.11n", "802.11g"], answer: 0, explanation: "Wi-Fi 6对应IEEE 802.11ax标准，提供更高的速率（最高9.6Gbps）、更好的并发连接能力和更低的功耗。Wi-Fi 5是802.11ac，Wi-Fi 4是802.11n。Wi-Fi 6E增加了6GHz频段。" },
  { q: "下列关于SDN（软件定义网络）的说法，正确的是？", options: ["将网络控制平面与数据平面分离", "用软件替代所有硬件", "不需要网络协议", "只能在局域网使用"], answer: 0, explanation: "SDN（Software-Defined Networking）将网络的控制平面与数据转发平面分离，通过软件集中控制网络。SDN提高了网络灵活性和可编程性，广泛应用于数据中心和运营商网络。" },
  { q: "下列关于CDN（内容分发网络）的说法，正确的是？", options: ["将内容缓存到离用户更近的节点提高访问速度", "是一种网络安全技术", "只用于视频分发", "是一种编程语言"], answer: 0, explanation: "CDN（Content Delivery Network）将网站内容缓存到全球各地的边缘节点，用户访问时从最近的节点获取内容，从而提高访问速度和可靠性。CDN广泛用于网站加速、视频直播等。" },
  { q: "下列关于量子密钥分发的说法，正确的是？", options: ["利用量子力学原理实现安全通信", "用量子计算机加密", "只能用于量子网络", "是一种传统加密方法"], answer: 0, explanation: "量子密钥分发（QKD）利用量子力学原理（如测不准原理和量子不可克隆定理）实现安全的密钥分发。任何窃听行为都会被检测到，理论上提供无条件安全的通信。" },
  { q: "联邦学习是一种？", options: ["保护隐私的分布式机器学习方法", "联邦政府的学习系统", "集中式机器学习", "无监督学习方法"], answer: 0, explanation: "联邦学习是一种保护隐私的分布式机器学习方法，多个参与方在不共享原始数据的情况下共同训练模型。联邦学习解决了数据孤岛和隐私保护问题，广泛应用于金融、医疗等领域。" },
  { q: "下列关于元宇宙的说法，正确的是？", options: ["元宇宙是虚拟与现实融合的数字世界", "元宇宙是一种虚拟货币", "元宇宙是一种编程语言", "元宇宙是一种操作系统"], answer: 0, explanation: "元宇宙（Metaverse）是利用虚拟现实、增强现实、区块链等技术构建的虚拟与现实融合的数字世界。元宇宙概念涵盖虚拟社交、虚拟经济、虚拟办公等多种应用场景。" },
  { q: "Web3.0的核心理念是？", options: ["去中心化和用户数据自主", "中心化管理和平台垄断", "仅用于桌面端", "取代互联网"], answer: 0, explanation: "Web3.0的核心理念是去中心化，强调用户对数据和数字资产的所有权和控制权。Web3.0结合区块链、智能合约等技术，实现读-写-拥有的互联网模式。" },
  { q: "下列关于数字证书的说法，正确的是？", options: ["用于验证身份和加密通信", "是一种数字货币", "是网页设计工具", "是操作系统"], answer: 0, explanation: "数字证书由权威机构（CA）颁发，用于验证网站或用户身份并加密通信。HTTPS协议使用SSL/TLS数字证书确保数据传输安全。数字证书包含公钥和身份信息。" },
  { q: "零信任安全架构的核心理念是？", options: ["从不信任，始终验证", "信任内部网络", "不需要身份验证", "只依赖防火墙"], answer: 0, explanation: "零信任安全架构的核心理念是从不信任，始终验证（Never trust, always verify），不区分内外网络，对所有访问请求都进行身份验证和授权。零信任适应了云计算和远程办公的安全需求。" },
  { q: "下列关于卫星互联网的说法，正确的是？", options: ["利用低轨卫星提供全球互联网接入", "只在地面使用", "速度比5G慢很多", "只用于军事"], answer: 0, explanation: "卫星互联网利用低轨（LEO）卫星星座提供全球互联网接入服务，如Starlink（星链）。低轨卫星具有低时延、高带宽的特点，可覆盖偏远地区和海洋，是6G天地一体化通信的重要组成部分。" },

  // 人工智能（20题）
  { q: "人工智能的英文缩写是？", options: ["AI", "ML", "DL", "NLP"], answer: 0, explanation: "人工智能（Artificial Intelligence, AI）是研究、开发用于模拟、延伸和扩展人类智能的理论、方法、技术和应用系统的一门学科。AI包括机器学习、深度学习、自然语言处理等多个子领域。" },
  { q: "机器学习的基本类型不包括？", options: ["量子学习", "监督学习", "无监督学习", "强化学习"], answer: 0, explanation: "机器学习的基本类型包括监督学习（有标签数据训练）、无监督学习（无标签数据训练）、半监督学习和强化学习（通过奖励机制学习）。量子学习不是机器学习的标准类型。" },
  { q: "深度学习的基础是？", options: ["人工神经网络", "决策树", "支持向量机", "贝叶斯网络"], answer: 0, explanation: "深度学习基于人工神经网络（特别是多层深层神经网络），通过多层非线性处理单元提取数据的层次特征。深度学习在图像识别、语音识别、自然语言处理等领域取得了突破性进展。" },
  { q: "下列关于神经网络的说法，正确的是？", options: ["神经网络模拟人脑神经元的工作方式", "神经网络就是人脑", "神经网络只能处理数字", "神经网络不需要训练"], answer: 0, explanation: "人工神经网络受生物神经元启发，由大量节点（神经元）通过连接组成，模拟人脑处理信息的方式。神经网络通过训练数据调整权重来学习。深度神经网络有多层隐藏层。" },
  { q: "ChatGPT属于哪种人工智能技术？", options: ["大语言模型", "计算机视觉", "机器人技术", "专家系统"], answer: 0, explanation: "ChatGPT是基于Transformer架构的大语言模型（LLM），由OpenAI开发。大语言模型通过在海量文本数据上训练，能生成流畅自然的文本，回答问题和进行对话。GPT-4等模型展现了强大的语言理解能力。" },
  { q: "图灵测试用于检验？", options: ["机器是否具有人类智能", "机器的计算速度", "网络的传输速度", "算法的正确性"], answer: 0, explanation: "图灵测试由艾伦·图灵于1950年提出，通过让人类与机器对话来判断机器是否具有智能。如果机器能让人类无法分辨它是人还是机器，则认为机器通过了图灵测试。图灵被誉为计算机科学之父。" },
  { q: "自然语言处理的英文缩写是？", options: ["NLP", "NLC", "NLA", "NLT"], answer: 0, explanation: "自然语言处理（Natural Language Processing, NLP）是AI的重要分支，研究计算机理解和生成人类自然语言。NLP应用包括机器翻译、语音识别、文本分析、智能问答等。ChatGPT就是NLP的典型应用。" },
  { q: "计算机视觉的主要任务是？", options: ["让计算机理解和处理图像信息", "让计算机生成文本", "让计算机进行数学运算", "让计算机管理网络"], answer: 0, explanation: "计算机视觉（Computer Vision, CV）让计算机理解和处理图像和视频信息，包括图像识别、目标检测、图像分割等。应用包括人脸识别、自动驾驶、医学影像分析等。" },
  { q: "下列关于强化学习的说法，正确的是？", options: ["通过试错和奖励机制学习", "需要标注数据", "只能用于游戏", "不需要任何反馈"], answer: 0, explanation: "强化学习是智能体通过与环境交互，在试错中学习最优策略，以获得最大累积奖励。AlphaGo就是强化学习的典型应用。强化学习不需要标注数据，适用于决策控制类问题。" },
  { q: "Transformer架构的核心机制是？", options: ["注意力机制", "卷积运算", "循环结构", "池化操作"], answer: 0, explanation: "Transformer架构的核心是自注意力机制（Self-Attention），能够并行处理序列数据，捕捉长距离依赖关系。Transformer是BERT、GPT等大语言模型的基础架构，由Google团队于2017年提出。" },
  { q: "下列关于生成对抗网络（GAN）的说法，正确的是？", options: ["由生成器和判别器两个网络组成", "只有一个网络", "只能用于分类", "不需要训练数据"], answer: 0, explanation: "生成对抗网络（GAN）由生成器和判别器两个网络组成，通过对抗训练生成逼真的数据（如图像）。生成器生成假数据，判别器区分真假，两者对抗优化。GAN广泛用于图像生成、风格迁移等。" },
  { q: "下列关于迁移学习的说法，正确的是？", options: ["将已学模型知识迁移到新任务", "将数据从一个服务器迁移到另一个", "迁移硬件设备", "迁移编程语言"], answer: 0, explanation: "迁移学习是将已在源任务上训练好的模型知识迁移到目标任务，减少目标任务对数据和训练时间的需求。迁移学习在实践中广泛应用，如预训练模型微调（fine-tuning）。" },
  { q: "人工智能发展三要素是？", options: ["数据、算法、算力", "硬件、软件、网络", "人员、资金、设备", "理论、实验、应用"], answer: 0, explanation: "人工智能发展的三要素是数据（训练材料）、算法（模型方法）和算力（计算能力）。近年来AI的快速发展得益于大数据的积累、深度学习算法的突破和GPU等算力的提升。" },
  { q: "下列关于ChatGPT的说法，正确的是？", options: ["由OpenAI开发的大语言模型", "由Google开发", "是操作系统", "是搜索引擎"], answer: 0, explanation: "ChatGPT由OpenAI开发，基于GPT（Generative Pre-trained Transformer）系列大语言模型。ChatGPT能进行自然语言对话、回答问题、生成文本和代码等，是生成式AI的代表性产品。" },
  { q: "下列关于AI伦理问题的说法，正确的是？", options: ["AI发展需要关注算法偏见、隐私保护和就业影响等伦理问题", "AI没有伦理问题", "AI伦理问题可以忽略", "AI伦理问题只有失业"], answer: 0, explanation: "AI发展面临诸多伦理问题：算法偏见（歧视）、隐私保护（数据滥用）、透明性（黑箱问题）、责任归属（事故责任）、就业影响（岗位替代）和安全隐患（恶意使用）。需要法规和伦理准则规范AI发展。" },
  { q: "下列关于知识图谱的说法，正确的是？", options: ["用图结构表示实体及其关系", "是一种地图", "是数据库管理系统", "是网络拓扑图"], answer: 0, explanation: "知识图谱用图结构表示实体（节点）及其关系（边），是结构化的知识库。知识图谱广泛应用于搜索引擎、智能问答、推荐系统等。Google知识图谱使搜索结果更智能化。" },
  { q: "下列关于推荐系统的说法，正确的是？", options: ["根据用户偏好推荐个性化内容", "随机推荐内容", "只推荐热门内容", "不需要用户数据"], answer: 0, explanation: "推荐系统根据用户的历史行为、偏好和相似用户的行为，推荐个性化内容（商品、新闻、视频等）。常用方法包括协同过滤、内容推荐和混合推荐。推荐系统是电商和内容平台的核心技术。" },
  { q: "下列关于AIGC的说法，正确的是？", options: ["AI生成内容，包括文本、图像、音频等", "AI读取内容", "AI删除内容", "AI分类内容"], answer: 0, explanation: "AIGC（AI-Generated Content）即AI生成内容，利用人工智能自动生成文本、图像、音频、视频等内容。AIGC代表产品有ChatGPT（文本）、Midjourney（图像）、Sora（视频）等，是AI的重要应用方向。" },
  { q: "AGI是指？", options: ["通用人工智能", "图形人工智能", "应用人工智能", "自动化人工智能"], answer: 0, explanation: "AGI（Artificial General Intelligence，通用人工智能）指具有与人类同等或超越人类智能的AI系统，能在各种任务中表现出通用智能。AGI目前尚未实现，是AI研究的终极目标之一。" },
  { q: "下列关于大模型微调的说法，正确的是？", options: ["在预训练模型基础上用特定数据进一步训练", "从头开始训练模型", "减少模型参数", "删除模型部分功能"], answer: 0, explanation: "微调（Fine-tuning）是在预训练大模型基础上，使用特定领域或任务的数据进一步训练，使模型适应特定任务。微调比从头训练更高效，是利用大模型的常用方法。" },

  // 航天技术（20题）
  { q: "中国第一颗人造卫星是？", options: ["东方红一号", "神舟一号", "嫦娥一号", "北斗一号"], answer: 0, explanation: "东方红一号是中国第一颗人造卫星，1970年4月24日发射成功，使中国成为继苏、美、法、日后第五个能独立发射卫星的国家。卫星播送《东方红》乐曲。" },
  { q: "中国第一位航天员是？", options: ["杨利伟", "聂海胜", "费俊龙", "翟志刚"], answer: 0, explanation: "杨利伟是中国第一位航天员，2003年10月15日乘神舟五号飞船进入太空，使中国成为继苏、美后第三个独立将人送入太空的国家。" },
  { q: "中国空间站的名称是？", options: ["天宫", "天和", "问天", "梦天"], answer: 0, explanation: "中国空间站名为天宫（Tiangong），由天和核心舱、问天实验舱和梦天实验舱组成。2022年完成在轨建造，可容纳3名航天员长期驻留。" },
  { q: "中国探月工程的名称是？", options: ["嫦娥工程", "天问工程", "北斗工程", "悟空工程"], answer: 0, explanation: "中国探月工程名为嫦娥工程，包括绕（嫦娥一、二号）、落（嫦娥三、四号）、回（嫦娥五号）三个阶段。嫦娥四号实现人类首次月球背面软着陆，嫦娥五号实现月球采样返回。" },
  { q: "中国火星探测任务的名称是？", options: ["天问一号", "嫦娥一号", "北斗一号", "悟空一号"], answer: 0, explanation: "天问一号是中国首次火星探测任务，2020年7月发射，2021年5月祝融号火星车成功着陆火星，使中国成为继美国后第二个成功着陆火星的国家。" },
  { q: "人类第一次登月是哪一年？", options: ["1969年", "1957年", "1972年", "1961年"], answer: 0, explanation: "1969年7月20日，美国阿波罗11号宇航员阿姆斯特朗成为第一个踏上月球的人，名言这是个人的一小步，却是人类的一大步。1957年苏联发射第一颗人造卫星Sputnik。" },
  { q: "中国北斗导航系统的英文名称是？", options: ["BDS", "GPS", "GLONASS", "Galileo"], answer: 0, explanation: "北斗卫星导航系统（BDS）是中国自主建设的全球卫星导航系统，2020年完成全球组网。与美国的GPS、俄罗斯的GLONASS和欧洲的Galileo并称全球四大卫星导航系统。" },
  { q: "世界上第一颗人造卫星是哪个国家发射的？", options: ["苏联", "美国", "中国", "法国"], answer: 0, explanation: "1957年10月4日，苏联发射了世界上第一颗人造卫星Sputnik 1（斯普特尼克1号），标志着人类进入太空时代，也引发了美苏太空竞赛。" },
  { q: "运载火箭的基本原理是？", options: ["反冲原理", "浮力原理", "电磁原理", "核裂变原理"], answer: 0, explanation: "运载火箭利用反冲原理工作：火箭发动机喷射高速气体，根据牛顿第三定律（作用力与反作用力），火箭获得反方向的推力。火箭不需要空气，可以在真空中飞行。" },
  { q: "地球同步轨道的高度约为？", options: ["36000公里", "400公里", "1000公里", "100公里"], answer: 0, explanation: "地球同步轨道高度约36000公里（确切为35786公里），在该轨道上的卫星与地球自转同步，相对地面静止。通信卫星和气象卫星通常使用地球同步轨道。国际空间站轨道高度约400公里。" },
  { q: "中国文昌航天发射场位于哪个省？", options: ["海南省", "甘肃省", "山西省", "四川省"], answer: 0, explanation: "文昌航天发射场位于海南省，是中国最南端的发射场，纬度低，利用地球自转离心力可节省燃料，适合发射大推力火箭和地球同步轨道卫星。酒泉在甘肃，太原在山西，西昌在四川。" },
  { q: "航天员在太空中处于失重状态的原因是？", options: ["在轨道上做自由落体运动", "太空中没有引力", "航天器屏蔽了引力", "航天员质量减小"], answer: 0, explanation: "航天员的失重并非太空中没有引力（引力仍然存在），而是航天器和航天员一起绕地球做自由落体运动（自由圆周运动），两者相对静止产生失重感。这等同于电梯自由下落时的失重。" },
  { q: "中国现役最大推力运载火箭是？", options: ["长征五号", "长征二号F", "长征七号", "长征十一号"], answer: 0, explanation: "长征五号（绰号胖五）是中国现役最大推力运载火箭，近地轨道运载能力约25吨，用于发射空间站舱段、火星探测器等大型航天器。长征二号F是目前唯一载人火箭。" },
  { q: "中国空间站首次太空授课的时间是？", options: ["2021年12月", "2003年10月", "2020年5月", "2016年10月"], answer: 0, explanation: "2021年12月，神舟十三号航天员王亚平在天宫空间站进行首次天宫课堂太空授课，展示了太空中的物理现象，全国青少年同步观看。此前2013年也在天宫一号上进行过太空授课。" },
  { q: "嫦娥四号创造的历史是？", options: ["人类首次月球背面软着陆", "首次登月", "首次月球采样返回", "首次火星着陆"], answer: 0, explanation: "嫦娥四号于2019年1月实现人类首次月球背面软着陆，通过鹊桥中继星与地球通信。月球背面着陆难度大，需要中继卫星支持。嫦娥四号还搭载了月球生物实验。" },
  { q: "国际空间站的英文缩写是？", options: ["ISS", "CSS", "TSS", "MSS"], answer: 0, explanation: "国际空间站（International Space Station, ISS）是由美、俄等16国联合建造的载人空间站，1998年开始建造，2000年首次有人驻留。ISS轨道高度约400公里，预计运营到2030年左右。" },
  { q: "下列关于可回收火箭的说法，正确的是？", options: ["火箭第一级可回收重复使用，降低发射成本", "整枚火箭都能回收", "可回收火箭不需要燃料", "只有中国掌握该技术"], answer: 0, explanation: "可回收火箭技术使火箭第一级（助推器）在发射后自主返回并重复使用，大幅降低发射成本。SpaceX的猎鹰9号是首个成功实现一级回收的火箭。中国也在研发可回收火箭技术。" },
  { q: "中国暗物质粒子探测卫星的名称是？", options: ["悟空", "墨子", "慧眼", "实践"], answer: 0, explanation: "悟空号是中国暗物质粒子探测卫星，2015年发射，通过探测宇宙高能粒子来寻找暗物质存在的证据。墨子号是世界首颗量子科学实验卫星（2016年发射）。慧眼号是硬X射线调制望远镜。" },
  { q: "下列关于太空垃圾的说法，正确的是？", options: ["太空垃圾会威胁航天器和航天员安全", "太空垃圾无害", "太空垃圾会自行消失", "太空垃圾只在低轨道存在"], answer: 0, explanation: "太空垃圾（空间碎片）包括废弃卫星、火箭碎片等，以极高速度运行，会威胁在轨航天器和航天员安全。太空垃圾碰撞会产生更多碎片（凯斯勒效应），需要空间碎片监测和减缓措施。" },
  { q: "James Webb太空望远镜的主要任务是？", options: ["观测宇宙早期星系和系外行星", "观测地球气候变化", "观测太阳活动", "观测小行星"], answer: 0, explanation: "詹姆斯韦伯太空望远镜（JWST）于2021年发射，是哈勃望远镜的继任者，主要观测宇宙早期星系formation、恒星形成和系外行星大气等。JWST工作在红外波段，位于地日L2拉格朗日点。" },

  // 新能源（20题）
  { q: "下列属于可再生能源的是？", options: ["太阳能", "煤炭", "石油", "天然气"], answer: 0, explanation: "太阳能是可再生能源（可不断补充）。煤炭、石油和天然气是化石能源，不可再生（形成需要数百万年）。可再生能源还包括风能、水能、生物质能、地热能和潮汐能等。" },
  { q: "太阳能光伏发电的原理是？", options: ["光生伏特效应", "光电效应", "光热转换", "光化学转换"], answer: 0, explanation: "太阳能光伏发电利用光生伏特效应（Photovoltaic Effect），当光照射半导体PN结时产生电动势。光伏电池主要材料是硅（单晶硅、多晶硅、非晶硅）。光热发电则是利用反射镜聚集阳光加热工质发电。" },
  { q: "风力发电机组的主要组成部分不包括？", options: ["蒸汽轮机", "风轮", "齿轮箱", "发电机"], answer: 0, explanation: "风力发电机组主要由风轮（叶片）、齿轮箱、发电机、偏航系统和控制系统等组成。蒸汽轮机是火力发电和核电站的设备，不是风力发电机组的组成部分。" },
  { q: "核能发电利用的是？", options: ["核裂变反应", "核聚变反应", "核衰变", "化学反应"], answer: 0, explanation: "目前核电站利用的是可控核裂变反应（铀-235或钚-239的裂变）。核聚变尚未实现商业化可控利用，国际热核聚变实验堆（ITER）正在建设中。核能是清洁高效的能源。" },
  { q: "氢能源的优点是？", options: ["燃烧产物只有水，无污染", "容易储存", "成本低", "自然存在丰富"], answer: 0, explanation: "氢能源燃烧产物只有水，零污染，是理想的清洁能源。但氢气储存运输困难（需要高压或液化），制氢成本高，且氢气不是自然存在的能源（需要从水或化石燃料中制取）。" },
  { q: "锂离子电池的优点不包括？", options: ["不含重金属污染", "能量密度高", "可重复充电", "循环寿命长"], answer: 0, explanation: "锂离子电池具有能量密度高、可重复充电、循环寿命长等优点。但锂电池也含有一定量的重金属和有机电解液，处理不当会污染环境。锂电池的安全性问题（如过热起火）也需关注。" },
  { q: "下列关于燃料电池的说法，正确的是？", options: ["将化学能直接转化为电能", "通过燃烧发电", "是储能装置", "只能用氢气"], answer: 0, explanation: "燃料电池通过电化学反应将燃料（如氢气）和氧化剂的化学能直接转化为电能，效率高且无燃烧过程。燃料电池不是储能装置而是发电装置，可使用氢气、甲醇等多种燃料。" },
  { q: "下列关于生物质能的说法，正确的是？", options: ["来源于动植物等有机物", "是不可再生能源", "是核能的一种", "只来源于植物"], answer: 0, explanation: "生物质能来源于动植物等有机物（如木材、农作物秸秆、沼气、生物乙醇等），是可再生能源。生物质能通过燃烧或生物化学转化释放能量。沼气（甲烷）是典型的生物质能。" },
  { q: "下列关于地热能的说法，正确的是？", options: ["利用地球内部热能发电或供暖", "来源于太阳辐射", "是不可再生能源", "只能在火山附近使用"], answer: 0, explanation: "地热能利用地球内部的热能进行发电或供暖，是可再生能源。地热资源主要分布在板块交界处（如冰岛、日本、中国西藏等）。地热发电分为干蒸汽、闪蒸汽和双循环三种类型。" },
  { q: "下列关于潮汐能的说法，正确的是？", options: ["利用潮汐涨落的势能发电", "利用海浪发电", "利用海水温差发电", "是不可再生能源"], answer: 0, explanation: "潮汐能利用潮汐涨落的水位差（势能）发电，是可再生能源。潮汐发电需要在海湾建坝，利用水位差驱动水轮机发电。潮汐能受月球和太阳引力影响，可预测。" },
  { q: "我国太阳能资源最丰富的地区是？", options: ["青藏高原", "四川盆地", "东北地区", "东南沿海"], answer: 0, explanation: "青藏高原海拔高、空气稀薄、日照时间长，太阳能资源最丰富。四川盆地多阴雨天气，太阳能资源较差。中国太阳能资源分布总体西多东少、北多南少。" },
  { q: "我国风能资源最丰富的地区是？", options: ["内蒙古和新疆", "四川盆地", "长江中下游", "华南地区"], answer: 0, explanation: "内蒙古、新疆和甘肃北部是我国风能资源最丰富的地区（三北地区），沿海地区风能也较丰富。我国正在建设多个大型风电基地，风电装机容量居世界第一。" },
  { q: "下列关于储能技术的说法，正确的是？", options: ["储能技术是新能源大规模利用的关键", "储能技术不重要", "储能只能用电池", "储能技术已完全成熟"], answer: 0, explanation: "储能技术是新能源（风能、太阳能等间歇性能源）大规模利用的关键，能在发电高峰时储存能量、用电高峰时释放。储能方式包括电化学储能（电池）、物理储能（抽水蓄能、压缩空气）等。" },
  { q: "下列关于光伏组件的说法，正确的是？", options: ["光伏组件将太阳光直接转化为直流电", "光伏组件将太阳光转化为热能", "光伏组件输出交流电", "光伏组件只能在白天使用"], answer: 0, explanation: "光伏组件（太阳能电池板）通过光生伏特效应将太阳光直接转化为直流电（DC），需要逆变器将直流电转换为交流电（AC）才能并网使用。光伏发电需要阳光，夜间不能发电。" },
  { q: "下列关于新能源乘用车的说法，正确的是？", options: ["包括纯电动、插电混动和燃料电池汽车", "只指纯电动汽车", "不包括混合动力汽车", "特指天然气汽车"], answer: 0, explanation: "新能源汽车主要包括纯电动汽车（BEV）、插电式混合动力汽车（PHEV）和燃料电池汽车（FCEV）。普通混合动力汽车（HEV）不属于新能源汽车。新能源汽车减少尾气排放，有利于环境保护。" },
  { q: "下列关于碳达峰和碳中和的说法，正确的是？", options: ["碳中和指净排放为零", "碳达峰指碳排放为零", "碳达峰指碳排放持续增加", "碳中和指不排放碳"], answer: 0, explanation: "碳达峰指碳排放总量达到历史最高值后逐步下降；碳中和指通过减排和碳汇（植树造林等）抵消碳排放，实现净排放为零。中国目标：2030年前碳达峰，2060年前碳中和。" },
  { q: "下列关于抽水蓄能电站的说法，正确的是？", options: ["利用电力低谷将水从下水库抽到上水库储存能量", "只能发电不能储能", "是化学储能方式", "不需要水资源"], answer: 0, explanation: "抽水蓄能电站在电力低谷时利用多余电力将水从下水库抽到上水库（储能），在电力高峰时放水发电（释能）。抽水蓄能是目前最成熟的大规模电力储能方式，储能效率约70%~80%。" },
  { q: "下列关于核聚变的说法，正确的是？", options: ["核聚变比核裂变释放更多能量且更安全", "核聚变已实现商业化", "核聚变产生大量放射性废物", "核聚变只能在太阳中发生"], answer: 0, explanation: "核聚变比核裂变释放更多能量，原料（氘、氚）丰富，且不产生长寿命放射性废物，更安全。但核聚变需要极高温度和压力条件，目前尚未实现可控核聚变的商业化。ITER项目正在推进相关研究。" },
  { q: "下列关于氢燃料电池汽车的说法，正确的是？", options: ["排放物只有水", "排放CO2", "使用汽油", "不需要加注燃料"], answer: 0, explanation: "氢燃料电池汽车以氢气为燃料，通过燃料电池将氢气与氧气反应产生电能驱动汽车，排放物只有水。氢燃料电池汽车加氢快、续航长，但加氢站等基础设施尚不完善。" },
  { q: "下列关于分布式能源的说法，正确的是？", options: ["在用户附近建设的小型能源系统", "只能建在远离用户的地区", "是大型集中式发电站", "只使用化石燃料"], answer: 0, explanation: "分布式能源是在用户附近建设的小型能源系统（如屋顶光伏、小型风电、燃料电池等），就近发电使用，减少输电损耗。分布式能源可与智能电网和微电网结合，提高能源利用效率。" },

  // 新材料（10题）
  { q: "石墨烯是？", options: ["单层碳原子构成的二维材料", "碳纳米管", "金刚石", "石墨"], answer: 0, explanation: "石墨烯是由单层碳原子以sp2杂化构成的二维蜂窝状结构材料，2004年由英国科学家Geim和Novoselov制备，获2010年诺贝尔物理学奖。石墨烯具有极高的导电性、导热性和强度。" },
  { q: "石墨烯的发现者是？", options: ["盖姆和诺沃肖洛夫", "居里夫人", "爱因斯坦", "费曼"], answer: 0, explanation: "英国曼彻斯特大学科学家安德烈盖姆和康斯坦丁诺沃肖洛夫于2004年用胶带剥离法成功制备出石墨烯，因此获得2010年诺贝尔物理学奖。石墨烯被称为新材料之王。" },
  { q: "碳纤维的特点是？", options: ["质量轻、强度高", "质量重、强度低", "导电性差", "不耐高温"], answer: 0, explanation: "碳纤维具有质量轻（不到钢的1/4）、强度高（钢的7~9倍）、耐高温、耐腐蚀等特点，广泛用于航空航天、体育器材、汽车等领域。碳纤维复合材料是重要的结构材料。" },
  { q: "纳米材料的特征尺寸范围是？", options: ["1~100纳米", "0.1~1纳米", "100~1000纳米", "1~10微米"], answer: 0, explanation: "纳米材料是指至少一个维度尺寸在1~100纳米范围内的材料。纳米材料具有小尺寸效应、表面效应和量子尺寸效应，表现出与宏观材料不同的物理化学性质。" },
  { q: "超导材料的特点是？", options: ["零电阻和完全抗磁性", "电阻极大", "无磁性", "高温下超导"], answer: 0, explanation: "超导材料在临界温度以下电阻为零（零电阻效应）且完全排斥磁场（迈斯纳效应/完全抗磁性）。目前超导材料需要极低温（液氮甚至液氦温度），室温超导是材料科学终极目标之一。" },
  { q: "下列关于高温超导的说法，正确的是？", options: ["高温超导指在液氮温度（77K）以上超导", "高温超导指室温超导", "高温超导已有商业应用", "高温超导不存在"], answer: 0, explanation: "高温超导是相对而言的高温（相对于绝对零度），指在液氮温度（77K/-196°C）以上出现超导现象的材料。高温超导材料（如钇钡铜氧）可使用廉价液氮冷却，有广泛应用前景。" },
  { q: "下列关于3D打印材料的说法，正确的是？", options: ["3D打印可使用塑料、金属、陶瓷等多种材料", "3D打印只能使用塑料", "3D打印材料有限", "3D打印不需要材料"], answer: 0, explanation: "3D打印（增材制造）可使用塑料（PLA、ABS）、金属（钛合金、不锈钢）、陶瓷、树脂等多种材料。3D打印技术通过逐层堆积材料制造三维物体，广泛用于快速原型和定制化生产。" },
  { q: "下列关于智能材料的说法，正确的是？", options: ["能感知环境变化并作出响应", "是人工智能硬件", "是新型半导体", "是生物材料"], answer: 0, explanation: "智能材料（形状记忆合金、压电材料、磁致伸缩材料等）能感知环境变化（温度、压力、电场等）并作出响应（改变形状、产生电信号等）。智能材料广泛应用于传感器、执行器等。" },
  { q: "下列关于复合材料的说法，正确的是？", options: ["由两种或以上不同材料组合而成", "是一种单一材料", "是金属材料", "是天然材料"], answer: 0, explanation: "复合材料由两种或以上不同材料组合而成，各组分保持各自特性且整体性能优于单一材料。如碳纤维增强复合材料（CFRP）、玻璃钢等，具有轻质高强等优点。" },
  { q: "下列关于可降解塑料的说法，正确的是？", options: ["可在自然环境中被微生物分解", "是不可分解的", "是有毒的", "是金属材料"], answer: 0, explanation: "可降解塑料能在自然环境中被微生物分解为水和CO2等无害物质，减少白色污染。常见可降解塑料包括PLA（聚乳酸）、PHA等生物降解塑料。可降解塑料是解决塑料污染的重要方向。" },

  // 生物医药（10题）
  { q: "mRNA疫苗的工作原理是？", options: ["将编码抗原的mRNA导入人体细胞表达抗原", "注射减毒病原体", "注射灭活病原体", "注射抗体"], answer: 0, explanation: "mRNA疫苗将编码病原体抗原蛋白的mRNA导入人体细胞，细胞利用mRNA合成抗原蛋白，激发免疫反应。mRNA疫苗具有研发速度快、免疫效果强等优点。新冠疫苗中辉瑞和莫德纳疫苗就是mRNA疫苗。" },
  { q: "CAR-T疗法主要用于治疗？", options: ["血液肿瘤", "感冒", "糖尿病", "心脏病"], answer: 0, explanation: "CAR-T（嵌合抗原受体T细胞）疗法是一种免疫细胞治疗方法，将患者T细胞基因改造后回输，使其特异性识别和杀伤肿瘤细胞。CAR-T疗法在B细胞淋巴瘤和白血病等血液肿瘤治疗中取得显著效果。" },
  { q: "精准医疗的核心理念是？", options: ["根据个体基因组信息定制治疗方案", "治疗所有人用同一方案", "只治疗遗传病", "使用最新设备"], answer: 0, explanation: "精准医疗根据个体的基因组、蛋白质组等信息，定制个性化的疾病预防和治疗方案。精准医疗克服了传统一刀切治疗的局限，在肿瘤治疗、药物选择等方面有重要应用。" },
  { q: "靶向治疗的特点是？", options: ["特异性作用于肿瘤细胞的特定分子靶点", "杀死所有快速分裂的细胞", "不区分正常和肿瘤细胞", "是手术的一种"], answer: 0, explanation: "靶向治疗特异性作用于肿瘤细胞的特定分子靶点（如突变的蛋白质），对正常细胞影响小，副作用较传统化疗低。如伊马替尼（格列卫）靶向BCR-ABL蛋白治疗慢性粒细胞白血病。" },
  { q: "免疫治疗是指？", options: ["利用人体免疫系统对抗疾病（如肿瘤）", "抑制免疫系统", "替换免疫系统", "使用抗生素"], answer: 0, explanation: "免疫治疗通过激活或增强人体免疫系统来对抗疾病，特别是肿瘤。免疫检查点抑制剂（如PD-1/PD-L1抗体）和CAR-T疗法是代表性的免疫治疗方法。免疫治疗被誉为肿瘤治疗的重大突破。" },
  { q: "基因检测可以用于？", options: ["疾病风险预测和个体识别", "治疗所有疾病", "改变基因", "制造基因"], answer: 0, explanation: "基因检测通过分析DNA序列用于疾病风险预测（如遗传病筛查、肿瘤风险）、个体识别（DNA指纹）、药物选择（药物基因组学）等。基因检测不能改变基因，也不能治疗所有疾病。" },
  { q: "下列关于再生医学的说法，正确的是？", options: ["利用干细胞等修复或替换受损组织和器官", "是器官移植", "是化学药物治疗", "是物理治疗"], answer: 0, explanation: "再生医学利用干细胞、组织工程等技术修复或替换受损组织和器官。干细胞具有分化潜能，可分化为各种细胞类型。3D生物打印技术可以打印组织和器官，再生医学前景广阔。" },
  { q: "下列关于液体活检的说法，正确的是？", options: ["通过血液等体液检测肿瘤DNA等标志物", "切除肿瘤组织检查", "是影像检查", "是血液透析"], answer: 0, explanation: "液体活检通过血液等体液检测循环肿瘤DNA（ctDNA）、循环肿瘤细胞等标志物，用于肿瘤早期筛查、疗效监测和预后评估。液体活检创伤小、可重复检测，是肿瘤诊断的重要发展方向。" },
  { q: "下列关于人工耳蜗的说法，正确的是？", options: ["将声音转化为电信号刺激听神经", "是助听器", "修复受损耳膜", "是药物治疗"], answer: 0, explanation: "人工耳蜗是一种电子医疗设备，将声音转化为电信号直接刺激听神经，帮助重度感音神经性耳聋患者恢复听力。人工耳蜗绕过受损的内耳毛细胞，是生物医学工程的重大成果。" },
  { q: "下列关于达芬奇手术机器人的说法，正确的是？", options: ["由外科医生操控的微创手术系统", "是自主手术机器人", "是诊断设备", "是康复设备"], answer: 0, explanation: "达芬奇手术机器人是由外科医生操控的微创手术系统，通过高清3D视觉和精密机械臂进行手术，具有创伤小、精度高、术后恢复快等优点。医生在控制台操作，机器人在患者身边执行手术。" },

  // 量子科技（10题）
  { q: "量子计算的基本单位是？", options: ["量子比特", "比特", "字节", "原子"], answer: 0, explanation: "量子计算的基本单位是量子比特（Qubit）。与经典比特（0或1）不同，量子比特可以处于0和1的叠加态。n个量子比特可以同时表示2的n次方种状态，使量子计算在某些问题上具有指数级加速能力。" },
  { q: "量子通信利用的原理是？", options: ["量子纠缠和量子不可克隆定理", "电磁感应", "光的折射", "热传导"], answer: 0, explanation: "量子通信利用量子纠缠和量子不可克隆定理实现安全通信。量子密钥分发（QKD）使任何窃听行为都会被检测到，理论上无条件安全。中国墨子号卫星实现了千公里级量子密钥分发。" },
  { q: "量子纠缠是指？", options: ["两个粒子的量子状态相互关联", "粒子相互碰撞", "粒子相互吸引", "粒子相互排斥"], answer: 0, explanation: "量子纠缠是指两个或多个粒子的量子状态相互关联，无论相距多远，对其中一个粒子的测量会瞬间影响另一个粒子的状态。爱因斯坦称之为鬼魅般的超距作用。量子纠缠是量子通信和量子计算的基础。" },
  { q: "量子计算机的优势在于？", options: ["某些特定问题具有指数级加速能力", "所有计算都比经典计算机快", "功耗更低", "价格更便宜"], answer: 0, explanation: "量子计算机在某些特定问题（如大数分解、量子模拟、搜索算法等）上具有指数级或平方级加速能力，但不是所有计算都快于经典计算机。量子计算适合解决经典计算机难以处理的复杂问题。" },
  { q: "Shor算法可以用于？", options: ["大数分解", "排序", "搜索", "压缩"], answer: 0, explanation: "Shor算法是量子算法，可以在多项式时间内分解大整数，比经典算法快指数倍。这意味着量子计算机一旦成熟，将威胁现有的RSA加密体系。因此后量子密码学（抗量子加密）研究日益重要。" },
  { q: "中国量子科学实验卫星的名称是？", options: ["墨子号", "悟空号", "嫦娥号", "天问号"], answer: 0, explanation: "墨子号是世界首颗量子科学实验卫星，2016年发射，由中国科学技术大学潘建伟团队主导。墨子号实现了千公里级量子密钥分发、量子纠缠分发和量子隐形传态，使中国在量子通信领域处于领先地位。" },
  { q: "量子叠加态是指？", options: ["量子系统同时处于多个状态的叠加", "量子系统只能处于一个状态", "量子系统不稳定", "量子系统消失"], answer: 0, explanation: "量子叠加态是量子系统同时处于多个状态的线性叠加。薛定谔的猫思想实验是叠加态的著名例子：在观测前猫处于死和活的叠加态。观测（测量）导致叠加态坍缩为确定状态。" },
  { q: "量子退相干是指？", options: ["量子系统与环境相互作用导致量子性质消失", "量子系统冷却", "量子系统加速", "量子系统重置"], answer: 0, explanation: "量子退相干是量子系统与环境的相互作用导致量子叠加态和纠缠态被破坏的过程。退相干是量子计算和量子通信面临的主要技术挑战，需要通过量子纠错和环境隔离来克服。" },
  { q: "下列关于量子密钥分发（QKD）的说法，正确的是？", options: ["理论无条件安全，能检测窃听", "完全不需要加密算法", "只用于军事通信", "速度比传统通信快"], answer: 0, explanation: "量子密钥分发（QKD）利用量子力学原理（测不准原理和不可克隆定理）实现理论无条件安全的密钥分发，任何窃听行为都会改变量子态而被检测到。QKD不是加密算法，而是安全的密钥传输方式。" },
  { q: "下列关于量子优势的说法，正确的是？", options: ["量子计算机在特定问题上超越经典计算机", "量子计算机全面超越经典计算机", "量子计算机更便宜", "量子计算机功耗更低"], answer: 0, explanation: "量子优势（量子霸权）指量子计算机在某个特定问题上超越最先进的经典超级计算机。2019年谷歌宣布其53量子比特处理器实现量子优势（随机数采样任务），但量子计算仍处于早期阶段。" },

  // ==================== 计算机基础（50题）====================
  // 计算机组成（10题）
  { q: "CPU的中文名称是？", options: ["中央处理器", "内存储器", "外存储器", "输入设备"], answer: 0, explanation: "CPU（Central Processing Unit）即中央处理器，是计算机的核心部件，负责执行指令和处理数据。CPU主要由运算器（ALU）和控制器（CU）组成。CPU的性能主要取决于主频、核心数和架构等。" },
  { q: "计算机内存的特点是？", options: ["速度快但断电后数据丢失", "速度慢但断电后数据不丢失", "容量比硬盘大", "属于外存储器"], answer: 0, explanation: "内存（RAM）是随机存取存储器，读写速度快但断电后数据丢失（易失性）。内存用于暂时存储CPU正在处理的数据和程序。硬盘等外存储器断电后数据不丢失（非易失性），但速度较慢。" },
  { q: "下列属于输入设备的是？", options: ["键盘", "显示器", "打印机", "音响"], answer: 0, explanation: "输入设备将外部信息输入计算机，如键盘、鼠标、扫描仪、麦克风等。输出设备将计算机处理结果输出，如显示器、打印机、音响等。触摸屏既是输入设备又是输出设备。" },
  { q: "下列属于输出设备的是？", options: ["显示器", "键盘", "鼠标", "扫描仪"], answer: 0, explanation: "输出设备将计算机处理的结果输出给用户，如显示器、打印机、音响、投影仪等。键盘、鼠标、扫描仪是输入设备。触摸屏既可输入也可输出。" },
  { q: "ROM的特点是？", options: ["只读存储器，断电后数据不丢失", "随机存取存储器，断电后数据丢失", "可随意写入", "是外存储器"], answer: 0, explanation: "ROM（Read-Only Memory）是只读存储器，数据在出厂时写入且断电后不丢失（非易失性）。ROM常用于存储BIOS等固件。RAM是随机存取存储器，断电后数据丢失。" },
  { q: "计算机存储容量的基本单位是？", options: ["字节", "位", "字", "扇区"], answer: 0, explanation: "字节（Byte，B）是计算机存储容量的基本单位。1B=8bit（位）。更大的单位有KB（1024B）、MB（1024KB）、GB（1024MB）、TB（1024GB）等。位是数据的最小单位。" },
  { q: "1GB等于多少MB？", options: ["1024MB", "1000MB", "512MB", "2048MB"], answer: 0, explanation: "计算机存储单位采用二进制换算：1KB=1024B，1MB=1024KB，1GB=1024MB，1TB=1024GB。注意硬盘厂商通常用十进制换算（1GB=1000MB），因此实际容量小于标称容量。" },
  { q: "CPU的主要性能指标不包括？", options: ["颜色数", "主频", "核心数", "缓存大小"], answer: 0, explanation: "CPU的主要性能指标包括主频（时钟频率）、核心数、线程数、缓存大小（L1/L2/L3 Cache）和架构等。颜色数是显示器的指标，与CPU性能无关。" },
  { q: "下列关于SSD固态硬盘的说法，正确的是？", options: ["读写速度快，无机械结构", "有机械结构", "速度比机械硬盘慢", "容量比机械硬盘大"], answer: 0, explanation: "SSD（固态硬盘）使用闪存芯片存储数据，无机械运动部件，读写速度快、抗震性好、功耗低、噪音小。相比传统机械硬盘（HDD），SSD速度更快但价格较高。" },
  { q: "计算机主板的功能是？", options: ["连接各硬件部件的基板", "处理数据", "存储数据", "显示图像"], answer: 0, explanation: "主板是计算机各部件连接的平台，提供CPU插槽、内存插槽、扩展接口等，连接CPU、内存、硬盘、显卡等各部件，使它们协同工作。主板的芯片组决定了支持的CPU和内存类型等。" },

  // 操作系统（8题）
  { q: "操作系统的作用是？", options: ["管理计算机硬件和软件资源", "处理文字", "浏览网页", "播放视频"], answer: 0, explanation: "操作系统是管理计算机硬件和软件资源的系统软件，提供用户与硬件之间的接口。操作系统功能包括处理器管理、存储管理、文件管理、设备管理和用户接口等。常见操作系统有Windows、Linux、macOS等。" },
  { q: "下列不属于操作系统的是？", options: ["Microsoft Office", "Windows", "Linux", "macOS"], answer: 0, explanation: "Microsoft Office是应用软件（办公套件），不是操作系统。Windows、Linux、macOS都是操作系统。操作系统是系统软件的核心，应用软件需要在操作系统上运行。" },
  { q: "Linux操作系统的特点是？", options: ["开源免费", "闭源收费", "只能用于服务器", "不支持网络"], answer: 0, explanation: "Linux是开源操作系统，内核由Linus Torvalds于1991年创建。Linux免费使用、源代码开放、稳定安全，广泛用于服务器、超级计算机和嵌入式设备。Android手机系统也基于Linux内核。" },
  { q: "下列关于macOS的说法，正确的是？", options: ["由苹果公司开发的操作系统", "由微软公司开发", "是开源系统", "只能在PC上运行"], answer: 0, explanation: "macOS是苹果公司开发的操作系统，仅运行在Mac系列电脑上。macOS基于Unix，界面美观、操作流畅。iOS是苹果手机操作系统，与macOS不同。" },
  { q: "Android操作系统的内核基于？", options: ["Linux内核", "Windows内核", "Unix内核", "macOS内核"], answer: 0, explanation: "Android操作系统由Google开发，基于Linux内核。Android是开源移动操作系统，广泛应用于智能手机和平板电脑。Android的应用层使用Java/Kotlin编程。" },
  { q: "iOS操作系统的开发者是？", options: ["苹果公司", "谷歌公司", "微软公司", "华为公司"], answer: 0, explanation: "iOS是苹果公司开发的移动操作系统，仅运行在iPhone、iPad等苹果设备上。iOS以流畅的用户体验和严格的应用审核著称。iOS基于Unix（Darwin内核）。" },
  { q: "Windows操作系统的开发者是？", options: ["微软公司", "苹果公司", "谷歌公司", "IBM公司"], answer: 0, explanation: "Windows是微软公司开发的操作系统，是全球使用最广泛的桌面操作系统。Windows 10/11是当前主要版本。微软还开发Windows Server服务器操作系统。" },
  { q: "下列关于文件系统的说法，正确的是？", options: ["组织和管理文件的方式", "是文字处理软件", "是网络协议", "是编程语言"], answer: 0, explanation: "文件系统是操作系统组织和管理文件的方式，决定文件的存储结构和访问方式。常见文件系统有NTFS（Windows）、ext4（Linux）、APFS（macOS）、FAT32（通用兼容）等。" },

  // 网络基础（12题）
  { q: "IP地址的作用是？", options: ["标识网络中的设备", "存储数据", "处理数据", "显示图像"], answer: 0, explanation: "IP地址用于在网络上唯一标识设备。IPv4地址为32位（如192.168.1.1），IPv6地址为128位。IP地址分为A、B、C、D、E五类，C类地址最常用。127.0.0.1是本地回环地址。" },
  { q: "IPv4地址由多少位二进制数组成？", options: ["32位", "64位", "128位", "16位"], answer: 0, explanation: "IPv4地址由32位二进制数组成，分为4段（每段8位），用十进制表示为xxx.xxx.xxx.xxx（如192.168.1.1）。IPv4地址空间约43亿个，已趋于枯竭，IPv6（128位）正在推广。" },
  { q: "域名系统（DNS）的功能是？", options: ["将域名转换为IP地址", "存储网页", "传输数据", "加密通信"], answer: 0, explanation: "DNS（Domain Name System）将域名（如www.baidu.com）转换为IP地址（如220.181.38.148），方便用户访问网站。DNS是互联网的基础服务，相当于电话簿。" },
  { q: "HTTP协议的中文含义是？", options: ["超文本传输协议", "文件传输协议", "简单邮件传输协议", "网络协议"], answer: 0, explanation: "HTTP（HyperText Transfer Protocol）即超文本传输协议，是Web浏览器与服务器之间传输网页数据的协议。HTTP使用80端口，HTTPS（加密版）使用443端口。HTTP是无状态协议。" },
  { q: "HTTPS相比HTTP增加了什么？", options: ["SSL/TLS加密", "更快的传输速度", "更大的数据容量", "更多的功能"], answer: 0, explanation: "HTTPS在HTTP基础上增加了SSL/TLS加密层，对传输数据进行加密，防止窃听和篡改。HTTPS使用443端口。现代网站普遍采用HTTPS保护用户数据安全。" },
  { q: "TCP/IP协议是？", options: ["互联网的基础通信协议", "一种编程语言", "一种操作系统", "一种硬件设备"], answer: 0, explanation: "TCP/IP是互联网的基础通信协议族，包括TCP（传输控制协议）和IP（网际协议）等。TCP提供可靠的数据传输，IP负责数据包的路由。TCP/IP分为四层：应用层、传输层、网络层和链路层。" },
  { q: "下列关于MAC地址的说法，正确的是？", options: ["网卡的物理地址，全球唯一", "与IP地址相同", "可以随意更改", "是苹果公司的地址"], answer: 0, explanation: "MAC地址是网卡的物理地址（硬件地址），由48位二进制组成（如00:1A:2B:3C:4D:5E），理论上全球唯一。MAC地址在数据链路层使用，IP地址在网络层使用。MAC与苹果公司无关（Media Access Control）。" },
  { q: "下列关于端口号的说法，正确的是？", options: ["标识网络应用进程", "标识网络设备", "是IP地址的一部分", "是物理接口"], answer: 0, explanation: "端口号用于标识主机上的网络应用进程，范围0~65535。常见端口：HTTP-80，HTTPS-443，FTP-21，SSH-22，DNS-53。一台主机可以通过不同端口同时运行多个网络服务。" },
  { q: "URL的中文含义是？", options: ["统一资源定位符", "统一资源标识符", "通用资源链接", "网络资源地址"], answer: 0, explanation: "URL（Uniform Resource Locator）即统一资源定位符，是互联网上资源的地址。URL格式：协议://域名:端口/路径/文件名。如https://www.example.com:443/index.html。" },
  { q: "下列关于路由器的说法，正确的是？", options: ["连接不同网络并转发数据包", "是输入设备", "是显示设备", "只用于无线上网"], answer: 0, explanation: "路由器是连接不同网络（如局域网与互联网）并在网络间转发数据包的设备。路由器根据IP地址选择最佳路径转发数据。家用路由器通常集成交换机、无线AP和防火墙功能。" },
  { q: "下列关于LAN的说法，正确的是？", options: ["局域网，覆盖范围小", "广域网，覆盖范围大", "互联网", "是无线网络"], answer: 0, explanation: "LAN（Local Area Network）即局域网，覆盖范围小（如办公室、学校），传输速率高。WAN（Wide Area Network）即广域网，覆盖范围大（如城市、国家）。互联网是全球最大的广域网。" },
  { q: "下列关于Wi-Fi的说法，正确的是？", options: ["无线局域网技术", "有线网络技术", "移动通信技术", "卫星通信技术"], answer: 0, explanation: "Wi-Fi是基于IEEE 802.11标准的无线局域网技术，允许设备通过无线方式接入网络。Wi-Fi使用2.4GHz和5GHz频段。Wi-Fi不是移动通信技术（如4G/5G），覆盖范围有限。" },

  // 编程基础（10题）
  { q: "二进制数1010对应的十进制数是？", options: ["10", "8", "12", "2"], answer: 0, explanation: "二进制转十进制：1010=1×2的3次方+0×2的2次方+1×2的1次方+0×2的0次方=8+0+2+0=10。计算机内部使用二进制表示数据，因为二进制只有0和1两个状态，便于电子器件实现。" },
  { q: "十进制数25对应的二进制数是？", options: ["11001", "10011", "10101", "11010"], answer: 0, explanation: "十进制转二进制（除2取余法）：25÷2=12余1，12÷2=6余0，6÷2=3余0，3÷2=1余1，1÷2=0余1。从下往上读：11001。验证：1×16+1×8+0×4+0×2+1×1=25。" },
  { q: "算法的基本特征不包括？", options: ["无限性", "有穷性", "确定性", "可行性"], answer: 0, explanation: "算法的基本特征包括：有穷性（在有限步骤内完成）、确定性（每一步有明确含义）、可行性（每一步可执行）、输入（0个或多个）和输出（1个或多个）。无限性不是算法的特征。" },
  { q: "数据结构中，栈的特点是？", options: ["后进先出（LIFO）", "先进先出（FIFO）", "随机访问", "双向访问"], answer: 0, explanation: "栈是后进先出（LIFO, Last In First Out）的数据结构，最后入栈的元素最先出栈。栈常用于函数调用、表达式求值等。队列是先进先出（FIFO）的数据结构。" },
  { q: "队列的特点是？", options: ["先进先出（FIFO）", "后进先出（LIFO）", "随机访问", "双向访问"], answer: 0, explanation: "队列是先进先出（FIFO, First In First Out）的数据结构，先入队的元素先出队。队列常用于任务调度、消息处理等。栈是后进先出（LIFO）的数据结构。" },
  { q: "下列关于排序算法的说法，正确的是？", options: ["快速排序的平均时间复杂度为O(n log n)", "快速排序的时间复杂度为O(n²)", "冒泡排序的时间复杂度为O(n log n)", "排序算法都是O(n)"], answer: 0, explanation: "快速排序的平均时间复杂度为O(n log n)，最坏情况为O(n²)。冒泡排序的时间复杂度为O(n²)。常见排序算法：快速排序、归并排序为O(n log n)，冒泡排序、选择排序、插入排序为O(n²)。" },
  { q: "下列关于程序设计语言的说法，正确的是？", options: ["C语言是编译型语言", "C语言是解释型语言", "Python是编译型语言", "Java不编译"], answer: 0, explanation: "C语言是编译型语言（先编译后运行），执行效率高。Python是解释型语言（逐行解释执行），开发效率高但执行较慢。Java先编译为字节码再由JVM解释执行，兼顾两者特点。" },
  { q: "下列关于面向对象编程的说法，正确的是？", options: ["核心概念包括封装、继承和多态", "是面向过程的编程方式", "不支持代码复用", "只有Java支持"], answer: 0, explanation: "面向对象编程（OOP）的三大特性是封装（隐藏实现细节）、继承（代码复用）和多态（同一接口不同实现）。Java、C++、Python等语言都支持OOP。" },
  { q: "下列关于变量的说法，正确的是？", options: ["变量是存储数据的命名容器", "变量不能改变值", "变量名可以数字开头", "变量不需要声明类型"], answer: 0, explanation: "变量是存储数据的命名容器，其值可以改变。变量名通常以字母或下划线开头，不能以数字开头。在强类型语言中变量需要声明类型，在弱类型语言中不需要。" },
  { q: "ASCII码用多少位二进制数表示一个字符？", options: ["7位", "8位", "16位", "32位"], answer: 0, explanation: "ASCII码用7位二进制数表示一个字符，共128个字符（0-127），包括英文字母、数字和常用符号。扩展ASCII码用8位（256个字符）。Unicode（如UTF-8）可以表示更多字符（包括中文）。" },

  // 信息安全（10题）
  { q: "下列关于对称加密的说法，正确的是？", options: ["加密和解密使用相同的密钥", "加密和解密使用不同密钥", "不需要密钥", "只能加密文本"], answer: 0, explanation: "对称加密使用相同的密钥进行加密和解密，如AES、DES等。对称加密速度快，但密钥管理困难（需要安全传输密钥）。非对称加密使用公钥和私钥两个密钥。" },
  { q: "下列关于非对称加密的说法，正确的是？", options: ["使用公钥和私钥两个密钥", "使用相同的密钥", "不需要密钥", "比对称加密快"], answer: 0, explanation: "非对称加密使用一对密钥：公钥（公开）和私钥（保密）。公钥加密的数据只能用私钥解密，反之亦然。常见算法有RSA、ECC等。非对称加密安全性高但速度较慢，常与对称加密结合使用。" },
  { q: "RSA加密算法是基于什么数学难题？", options: ["大数分解", "离散对数", "最短向量", "背包问题"], answer: 0, explanation: "RSA加密算法基于大数分解的数学难题。RSA使用两个大素数的乘积作为公钥的一部分，分解大数为素数非常困难。RSA广泛应用于安全通信（如HTTPS、数字签名等）。" },
  { q: "防火墙的功能是？", options: ["控制网络访问，过滤不安全数据", "杀灭计算机病毒", "加速网络访问", "存储数据"], answer: 0, explanation: "防火墙是网络安全设备，根据安全策略控制网络访问，过滤不安全的数据包，保护内部网络安全。防火墙分为硬件防火墙和软件防火墙，可阻止未授权访问和攻击。" },
  { q: "计算机病毒的特征不包括？", options: ["无害性", "传染性", "隐蔽性", "破坏性"], answer: 0, explanation: "计算机病毒的特征包括传染性（自我复制传播）、隐蔽性（不易被发现）、破坏性（破坏数据和系统）、潜伏性和可触发性等。无害性不是病毒的特征，病毒都有不同程度的危害。" },
  { q: "下列关于钓鱼网站的说法，正确的是？", options: ["冒充合法网站骗取用户信息", "是钓鱼的网站", "是安全网站", "是政府网站"], answer: 0, explanation: "钓鱼网站冒充合法网站（如银行、电商），骗取用户的账号密码等敏感信息。防范方法：核实网址、不点击可疑链接、使用安全证书验证（HTTPS）等。" },
  { q: "数字签名的作用是？", options: ["验证发送者身份和数据完整性", "加密数据", "压缩数据", "传输数据"], answer: 0, explanation: "数字签名利用非对称加密技术验证发送者身份（不可抵赖）和数据完整性（不可篡改）。发送方用私钥签名，接收方用公钥验证。数字签名广泛用于电子合同、电子商务等。" },
  { q: "下列关于SQL注入的说法，正确的是？", options: ["通过注入恶意SQL语句攻击数据库", "是硬件攻击", "是物理攻击", "是网络协议漏洞"], answer: 0, explanation: "SQL注入是通过在输入中注入恶意SQL语句来攻击数据库的安全漏洞，可导致数据泄露或篡改。防范方法：使用参数化查询、输入验证和最小权限原则等。" },
  { q: "下列关于社会工程学的说法，正确的是？", options: ["利用人性弱点获取机密信息", "是工程技术", "是编程技术", "是网络协议"], answer: 0, explanation: "社会工程学利用人性弱点（如信任、好奇心、恐惧等）通过欺骗手段获取机密信息，如冒充客服骗取密码。防范方法：提高安全意识、验证身份、不轻信陌生人等。" },
  { q: "下列关于多因素认证的说法，正确的是？", options: ["结合多种认证方式提高安全性", "只用密码认证", "不需要认证", "只用生物特征"], answer: 0, explanation: "多因素认证（MFA）结合两种或以上认证方式（如密码+手机验证码、密码+指纹等），提高账户安全性。即使密码泄露，攻击者也难以通过其他认证因素。MFA是重要的安全措施。" },

  // ==================== 生活科技（50题）====================
  // 家用电器原理（10题）
  { q: "微波炉加热食物的原理是？", options: ["微波使食物中水分子振动产生热量", "通过红外线加热", "通过电阻加热", "通过明火加热"], answer: 0, explanation: "微波炉利用频率为2.45GHz的微波使食物中的水分子高速振动产生热量。微波能穿透食物内部加热，因此加热速度快。金属容器会反射微波不能用，应使用微波专用容器。" },
  { q: "空调制冷的原理是？", options: ["制冷剂在蒸发和冷凝过程中吸收和释放热量", "通过电风扇降温", "通过冰块降温", "通过水蒸发降温"], answer: 0, explanation: "空调利用制冷剂（如氟利昂）在压缩机、冷凝器、膨胀阀和蒸发器之间循环，制冷剂在室内蒸发吸收热量（制冷），在室外冷凝释放热量。空调还兼具除湿和制热功能。" },
  { q: "电饭煲煮饭的原理是？", options: ["利用电阻丝加热和温控开关控制温度", "利用微波加热", "利用电磁感应加热", "利用蒸汽加热"], answer: 0, explanation: "电饭煲利用电阻丝（加热盘）加热，通过温控开关（磁性温控元件）控制温度。当温度达到100°C时水沸腾维持恒温，水干后温度升至103°C左右，温控开关自动断电进入保温状态。" },
  { q: "电磁炉的工作原理是？", options: ["电磁感应使锅底产生涡流发热", "电阻加热", "红外线加热", "微波加热"], answer: 0, explanation: "电磁炉利用电磁感应原理，线圈产生交变磁场，在铁磁性锅底产生感应电流（涡流），涡流使锅底自身发热。因此电磁炉只能使用铁磁性锅具（铁锅、不锈钢锅），不能用玻璃锅或铝锅。" },
  { q: "冰箱的工作原理是？", options: ["制冷剂循环吸收和释放热量", "通过冰块制冷", "通过电风扇制冷", "通过水制冷"], answer: 0, explanation: "冰箱与空调原理类似，利用制冷剂在压缩机驱动下循环，在蒸发器（冰箱内部）吸收热量制冷，在冷凝器（冰箱外部）释放热量。冰箱通过温控器控制压缩机工作维持低温。" },
  { q: "下列关于LED灯的说法，正确的是？", options: ["发光效率高、寿命长、节能", "比白炽灯更耗电", "寿命短", "不含半导体"], answer: 0, explanation: "LED灯利用半导体材料电致发光，具有发光效率高、寿命长（可达5万小时以上）、节能省电、响应快等优点。LED灯不含汞等有害物质，是绿色照明产品。" },
  { q: "下列关于洗衣机的说法，正确的是？", options: ["通过电机驱动波轮或滚筒搅动清洗衣物", "通过超声波清洗", "通过微波清洗", "通过蒸汽清洗"], answer: 0, explanation: "洗衣机通过电机驱动波轮（波轮式）或滚筒（滚筒式）搅动衣物，配合水和洗涤剂清洗。滚筒洗衣机对衣物磨损小、用水少但价格较高；波轮洗衣机洗涤速度快、价格低。" },
  { q: "下列关于扫地机器人的说法，正确的是？", options: ["利用传感器和算法自主清扫", "需要人工操控", "只能清扫地毯", "是手动工具"], answer: 0, explanation: "扫地机器人利用各种传感器（激光雷达、红外、碰撞等）和SLAM算法自主导航和建图，自动清扫地面。扫地机器人集成了吸尘、拖地等功能，是智能家居的重要产品。" },
  { q: "下列关于空气净化器的说法，正确的是？", options: ["通过滤网过滤和吸附净化空气", "产生氧气", "升高室温", "增加湿度"], answer: 0, explanation: "空气净化器通过多层滤网（初效滤网、HEPA滤网、活性炭滤网等）过滤颗粒物（PM2.5等）和吸附有害气体（甲醛等），净化室内空气。部分净化器还具有紫外线杀菌和负离子功能。" },
  { q: "下列关于智能音箱的说法，正确的是？", options: ["通过语音识别和自然语言理解实现交互", "只能播放音乐", "是普通音箱", "需要键盘操作"], answer: 0, explanation: "智能音箱内置语音助手（如小爱同学、天猫精灵等），通过语音识别和自然语言理解技术实现语音交互，可控制智能家居、播放音乐、查询信息等。智能音箱是智能家居的控制中心之一。" },

  // 交通技术（10题）
  { q: "中国高铁的最高运营速度是？", options: ["350km/h", "250km/h", "200km/h", "500km/h"], answer: 0, explanation: "中国高铁最高运营速度为350km/h（复兴号）。京沪高铁等线路运营速度达350km/h。中国高铁总里程超过4万公里，居世界第一。高铁技术是中国自主创新的重要成果。" },
  { q: "下列关于新能源汽车的说法，正确的是？", options: ["包括纯电动、插电混动和燃料电池汽车", "只指纯电动汽车", "指天然气汽车", "指太阳能汽车"], answer: 0, explanation: "新能源汽车包括纯电动汽车（BEV）、插电式混合动力汽车（PHEV）和燃料电池汽车（FCEV）。普通混合动力汽车（HEV）不属于新能源汽车。新能源汽车减少尾气排放，有利于环境保护。" },
  { q: "自动驾驶等级中，L5级是指？", options: ["完全自动驾驶，无需人类干预", "辅助驾驶", "部分自动驾驶", "有条件自动驾驶"], answer: 0, explanation: "根据SAE标准，自动驾驶分为L0~L5六个等级。L5为完全自动驾驶，在所有道路和环境下无需人类干预。L2为部分自动化（如自适应巡航+车道保持），L3为有条件自动化。目前量产车主要在L2~L3级别。" },
  { q: "下列关于共享单车的说法，正确的是？", options: ["利用物联网和GPS定位技术管理", "不需要任何技术", "只能用现金支付", "是私人自行车"], answer: 0, explanation: "共享单车利用物联网、GPS定位、移动支付等技术实现无桩租赁。用户通过手机APP扫码解锁，使用后停放在指定区域。共享单车解决了最后一公里出行问题，是共享经济的典型应用。" },
  { q: "下列关于ETC的说法，正确的是？", options: ["电子不停车收费系统", "电子交通监控", "电子导航系统", "电子计时系统"], answer: 0, explanation: "ETC（Electronic Toll Collection）即电子不停车收费系统，利用车载OBU与收费站的RSU进行微波通信，实现不停车自动缴费。ETC提高了高速公路通行效率，减少拥堵和排放。" },
  { q: "下列关于导航系统的说法，正确的是？", options: ["利用卫星定位确定位置和规划路线", "只使用地面基站", "不需要卫星", "只能用于汽车"], answer: 0, explanation: "导航系统利用卫星定位（如GPS、北斗等）确定用户位置，结合地图数据规划最优路线。智能手机导航结合了卫星定位、基站定位和Wi-Fi定位等多种技术提高定位精度。" },
  { q: "下列关于磁悬浮列车的说法，正确的是？", options: ["利用磁力使列车悬浮并推动前进", "利用蒸汽推动", "利用电力推动车轮", "利用风力推动"], answer: 0, explanation: "磁悬浮列车利用电磁力使列车悬浮在轨道上方（无接触），通过直线电机推动前进。磁悬浮列车无摩擦、噪音低、速度高。上海磁浮线最高运营速度430km/h，是高速交通的重要方向。" },
  { q: "下列关于无人机的说法，正确的是？", options: ["通过遥控或自主程序飞行的无人飞行器", "是有人驾驶飞机", "是导弹", "是卫星"], answer: 0, explanation: "无人机（UAV）是通过遥控或自主程序飞行的无人飞行器，利用GPS、陀螺仪、气压计等传感器实现飞行控制。无人机广泛应用于航拍、农业植保、物流配送、测绘等领域。" },
  { q: "下列关于电动汽车电池的说法，正确的是？", options: ["锂电池是目前主流的动力电池", "铅酸电池是主流", "电池不需要管理", "电池无安全隐患"], answer: 0, explanation: "锂电池（特别是磷酸铁锂和三元锂电池）是目前电动汽车的主流动力电池，具有能量密度高、循环寿命长等优点。电池管理系统（BMS）监控电池状态确保安全。电池安全和续航是电动车关键问题。" },
  { q: "下列关于智慧交通的说法，正确的是？", options: ["利用信息技术优化交通管理和出行", "是传统交通", "只用于高速公路", "不需要数据"], answer: 0, explanation: "智慧交通利用物联网、大数据、AI等技术优化交通管理和出行，包括智能信号灯、实时路况分析、智能停车等。智慧交通提高道路效率、减少拥堵和事故，是智慧城市的重要组成部分。" },

  // 农业科技（10题）
  { q: "杂交水稻的培育者是？", options: ["袁隆平", "钱学森", "茅以升", "华罗庚"], answer: 0, explanation: "袁隆平是中国杂交水稻的开创者，被誉为杂交水稻之父。他培育的杂交水稻使水稻产量大幅提高，为中国和世界粮食安全作出巨大贡献。袁隆平于2019年获得共和国勋章。" },
  { q: "杂交水稻利用的原理是？", options: ["杂种优势", "基因突变", "自然选择", "人工诱变"], answer: 0, explanation: "杂交水稻利用杂种优势——两个遗传基础不同的亲本杂交产生的杂种一代（F1）在生长势、适应性、产量等方面优于双亲。利用雄性不育系实现大规模杂交制种是关键技术。" },
  { q: "下列关于转基因作物的说法，正确的是？", options: ["通过基因工程技术导入外源基因", "通过传统杂交获得", "是自然变异", "是化学诱变"], answer: 0, explanation: "转基因作物通过基因工程技术将外源基因（如抗虫基因、抗除草剂基因）导入作物基因组。转基因作物可提高产量、减少农药使用。常见转基因作物有转基因棉花、玉米、大豆等。" },
  { q: "滴灌技术的优点是？", options: ["节水高效，减少蒸发", "耗水量大", "成本极低", "不适合大面积使用"], answer: 0, explanation: "滴灌技术将水通过管道直接滴到植物根部，节水效率高（比传统灌溉节水30%~50%），减少蒸发和深层渗漏，还可结合施肥（水肥一体化）。滴灌特别适合干旱缺水地区。" },
  { q: "下列关于无土栽培的说法，正确的是？", options: ["不用土壤，用营养液培养植物", "不用水", "不用肥料", "只能在室内"], answer: 0, explanation: "无土栽培不用天然土壤，用营养液为植物提供养分。无土栽培包括水培、基质培和雾培等方式，可控制养分供应，减少土传病害，提高产量和品质，广泛用于设施农业。" },
  { q: "下列关于智慧农业的说法，正确的是？", options: ["利用物联网、大数据等技术管理农业", "是传统农业", "只用于种植", "不需要技术"], answer: 0, explanation: "智慧农业利用物联网、大数据、AI、无人机等技术实现精准种植和管理，包括土壤监测、智能灌溉、病虫害预警等。智慧农业提高农业生产效率和资源利用率，是农业现代化的重要方向。" },
  { q: "下列关于农业无人机的说法，正确的是？", options: ["用于植保喷药和农田监测", "只能拍照", "是载人飞行器", "不需要遥控"], answer: 0, explanation: "农业无人机用于植保（喷药、施肥）、农田监测（航拍测绘）等，具有效率高、不受地形限制、减少农药暴露等优点。植保无人机配备精准喷洒系统，可实现变量喷洒。" },
  { q: "下列关于温室大棚的说法，正确的是？", options: ["通过控制温度湿度等环境条件促进植物生长", "只能种花", "不需要阳光", "是自然种植"], answer: 0, explanation: "温室大棚通过覆盖材料（玻璃、薄膜等）控制温度、湿度、光照等环境条件，创造适宜植物生长的环境，实现反季节种植和提高产量。现代化温室配备自动控制系统，实现精准环境调控。" },
  { q: "下列关于基因编辑作物的说法，正确的是？", options: ["使用CRISPR等技术精确修改作物基因", "导入外源基因", "是传统杂交", "是化学诱变"], answer: 0, explanation: "基因编辑作物使用CRISPR-Cas9等技术精确修改作物自身基因（不导入外源基因），改善作物性状（如抗病、增产等）。基因编辑与转基因不同，在监管上可能有不同政策。" },
  { q: "下列关于生态农业的说法，正确的是？", options: ["遵循生态原理，减少化学投入品使用", "大量使用化肥农药", "是传统农业", "只追求产量"], answer: 0, explanation: "生态农业遵循生态学原理，利用生物多样性、物质循环等机制减少化肥农药使用，兼顾经济效益和生态效益。生态农业模式包括稻鱼共生、立体种植等，是实现可持续农业的重要途径。" },

  // 医学常识（10题）
  { q: "正常成年人的血压范围是？", options: ["收缩压90~139mmHg，舒张压60~89mmHg", "收缩压80~120mmHg，舒张压50~70mmHg", "收缩压100~160mmHg，舒张压70~100mmHg", "收缩压70~100mmHg，舒张压40~60mmHg"], answer: 0, explanation: "正常血压：收缩压90~139mmHg，舒张压60~89mmHg。高血压标准：收缩压≥140mmHg和/或舒张压≥90mmHg。高血压是心脑血管疾病的重要危险因素，需要定期监测和控制。" },
  { q: "正常空腹血糖范围是？", options: ["3.9~6.1mmol/L", "6.1~7.0mmol/L", "7.0~11.1mmol/L", "2.0~5.0mmol/L"], answer: 0, explanation: "正常空腹血糖为3.9~6.1mmol/L。空腹血糖≥7.0mmol/L或餐后2小时血糖≥11.1mmol/L可诊断为糖尿病。空腹血糖6.1~7.0mmol/L为空腹血糖受损（糖尿病前期）。" },
  { q: "下列关于疫苗的说法，正确的是？", options: ["疫苗是预防传染病的生物制品", "疫苗能治疗所有疾病", "疫苗是抗生素", "疫苗有百害无一利"], answer: 0, explanation: "疫苗是用病原微生物或其成分制成的生物制品，通过刺激机体产生免疫反应来预防传染病。常见疫苗有乙肝疫苗、流感疫苗、新冠疫苗等。疫苗接种是预防传染病最经济有效的措施。" },
  { q: "下列关于抗生素的说法，正确的是？", options: ["抗生素对病毒感染无效", "抗生素能杀灭病毒", "抗生素是万能药", "抗生素没有副作用"], answer: 0, explanation: "抗生素只对细菌、真菌等有效，对病毒感染（如感冒、流感、新冠肺炎等）无效。滥用抗生素会导致细菌耐药性增加、破坏正常菌群等危害。使用抗生素应遵医嘱，不自行购买使用。" },
  { q: "下列关于人体正常体温的说法，正确的是？", options: ["腋下温度正常范围36.0~37.0°C", "口腔温度37.5°C正常", "腋下温度38.0°C正常", "体温是恒定不变的"], answer: 0, explanation: "正常体温：腋下36.0~37.0°C，口腔36.3~37.2°C，直肠36.5~37.7°C。腋下温度超过37.3°C为发热。体温有昼夜波动（清晨最低，下午最高），女性排卵期体温略高。" },
  { q: "下列关于血型的说法，正确的是？", options: ["ABO血型系统包括A、B、AB、O四种", "血型只有一种分类系统", "O型血是万能受血者", "AB型血是万能供血者"], answer: 0, explanation: "ABO血型系统有A、B、AB、O四种血型。O型血是万能供血者（红细胞无A、B抗原），AB型血是万能受血者（血浆无抗A、抗B抗体）。输血应同型输注，紧急情况下可酌情异型输血。" },
  { q: "下列关于心肺复苏（CPR）的说法，正确的是？", options: ["包括胸外按压和人工呼吸", "只需人工呼吸", "只需胸外按压", "不适用于心脏骤停"], answer: 0, explanation: "心肺复苏（CPR）包括胸外按压（按压深度5-6cm，频率100-120次/分）和人工呼吸（按压与吹气比例30:2）。CPR用于心脏骤停患者的急救，黄金抢救时间为4-6分钟。" },
  { q: "下列关于合理膳食的说法，正确的是？", options: ["食物多样，谷类为主", "只吃肉类", "只吃蔬菜", "不吃早餐"], answer: 0, explanation: "合理膳食原则：食物多样、谷类为主；多吃蔬果、奶类、大豆；适量吃鱼禽蛋瘦肉；少盐少油控糖。中国居民膳食指南建议每天摄入12种以上食物，每周25种以上。" },
  { q: "下列关于睡眠的说法，正确的是？", options: ["成年人每天建议睡眠7~9小时", "成年人只需4小时睡眠", "睡眠越多越好", "熬夜不影响健康"], answer: 0, explanation: "成年人每天建议睡眠7~9小时。长期睡眠不足会增加心血管疾病、肥胖、免疫力下降等风险。良好的睡眠习惯包括规律作息、避免睡前使用电子设备、保持安静舒适的睡眠环境。" },
  { q: "下列关于心理健康的说法，正确的是？", options: ["心理健康与身体健康同样重要", "心理健康不重要", "心理问题不需要关注", "只有严重疾病才需要治疗"], answer: 0, explanation: "心理健康与身体健康同样重要，是健康的重要组成部分。保持心理健康的方法：积极乐观的心态、良好的人际关系、适度运动、合理宣泄情绪、必要时寻求专业心理咨询帮助。" },
];
